def append_unique_capped(values: object, item: object, max_items: int) -> list[str]:
    """Append unique capped."""
    item_text = str(item)
    existing = [str(value) for value in values] if isinstance(values, list) else []
    existing = [value for value in existing if value != item_text]
    existing.append(item_text)
    return existing[-max_items:]


def append_unique_durable(values: object, item: object) -> list[str]:
    """Append once without evicting an authoritative completed-target record."""
    item_text = str(item)
    existing = [str(value) for value in values] if isinstance(values, list) else []
    deduplicated = list(dict.fromkeys(existing))
    if item_text not in deduplicated:
        deduplicated.append(item_text)
    return deduplicated


def bounded_tweet_id_value(value: object, *, allow_empty: bool = False) -> int | None:
    """Parse one bounded string tweet ID without unbounded integer conversion."""
    if allow_empty and value == "":
        return 0
    if type(value) is not str or not re.fullmatch(r"\d{1,30}", value):
        return None
    return int(value)


def normalise_state_int(value: object, *, key: str, path: Path) -> int | None:
    """Normalise state int."""
    if isinstance(value, bool):
        log.error("State candidate %s has invalid %s boolean value %r; ignoring", path, key, value)
        return None
    if isinstance(value, float) and (not math.isfinite(value) or not value.is_integer()):
        log.error("State candidate %s has invalid %s numeric value %r; ignoring", path, key, value)
        return None
    try:
        number = int(value or 0)
    except (TypeError, ValueError, OverflowError):
        log.error("State candidate %s has invalid %s value %r; ignoring", path, key, value)
        return None
    if number < 0:
        log.error("State candidate %s has negative %s value %r; ignoring", path, key, value)
        return None
    return number


def normalise_state_epoch(value: object, *, key: str, path: Path) -> int | None:
    """Normalise state epoch."""
    number = normalise_state_int(value, key=key, path=path)
    if number is None:
        return None
    if number > MAX_REASONABLE_STATE_EPOCH:
        log.error("State candidate %s has impossible epoch %s=%r; ignoring", path, key, value)
        return None
    return number


def normalise_string_list(value: object, *, key: str, path: Path) -> list[str] | None:
    """Normalise string list."""
    if not isinstance(value, list):
        log.error("State candidate %s has invalid %s type %s; ignoring", path, key, type(value).__name__)
        return None
    return [str(item) for item in value if item is not None]


def normalise_recent_confirmed_regular_images(
    value: object, *, path: Path
) -> list[dict[str, str]] | None:
    """Validate the bounded, ordered confirmed regular-image history."""
    if not isinstance(value, list) or len(value) > RECENT_CONFIRMED_REGULAR_IMAGES_MAX:
        log.error(
            "State candidate %s has invalid recent confirmed-image history; ignoring",
            path,
        )
        return None
    result: list[dict[str, str]] = []
    post_ids: set[str] = set()
    for item in value:
        if not isinstance(item, dict) or set(item) != {
            "post_id",
            "image_basename",
            "image_sha256",
        }:
            log.error(
                "State candidate %s has malformed recent confirmed-image record; ignoring",
                path,
            )
            return None
        post_id = item.get("post_id")
        basename = item.get("image_basename")
        image_hash = item.get("image_sha256")
        if (
            type(post_id) is not str
            or re.fullmatch(r"\d{1,30}", post_id) is None
            or post_id in post_ids
            or not valid_receipt_basename(basename)
            or type(image_hash) is not str
            or re.fullmatch(r"[0-9a-f]{64}", image_hash) is None
        ):
            log.error(
                "State candidate %s has impossible recent confirmed-image identity; ignoring",
                path,
            )
            return None
        post_ids.add(post_id)
        result.append(
            {
                "post_id": post_id,
                "image_basename": str(basename),
                "image_sha256": image_hash,
            }
        )
    return result


def record_recent_confirmed_regular_image(
    state: dict,
    *,
    post_id: object,
    image_basename: object,
    image_sha256: object,
) -> bool:
    """Append one confirmed post exactly once and keep only 64 records."""
    candidate = {
        "post_id": str(post_id or ""),
        "image_basename": str(image_basename or ""),
        "image_sha256": str(image_sha256 or ""),
    }
    current = state.get("recent_confirmed_regular_images", [])
    validated = normalise_recent_confirmed_regular_images(current, path=STATE_FILE)
    if validated is None:
        open_original_editorial_circuit_breaker("recent_history_invalid")
        raise RuntimeError("Recent confirmed regular-image state is corrupt")
    matching = [item for item in validated if item["post_id"] == candidate["post_id"]]
    if matching:
        if matching[0] != candidate:
            open_original_editorial_circuit_breaker("recent_history_invalid")
            raise RuntimeError("Confirmed post identity conflicts with recent-image state")
        return False
    validated_candidate = normalise_recent_confirmed_regular_images(
        [candidate], path=STATE_FILE
    )
    if validated_candidate is None:
        open_original_editorial_circuit_breaker("recent_history_invalid")
        raise RuntimeError("Cannot record impossible confirmed regular-image identity")
    state["recent_confirmed_regular_images"] = (
        validated + validated_candidate
    )[-RECENT_CONFIRMED_REGULAR_IMAGES_MAX:]
    return True


def normalise_int_list(value: object, *, key: str, path: Path) -> list[int] | None:
    """Normalise int list."""
    if not isinstance(value, list):
        log.error("State candidate %s has invalid %s type %s; ignoring", path, key, type(value).__name__)
        return None
    out: list[int] = []
    for item in value:
        number = normalise_state_int(item, key=key, path=path)
        if number is None:
            return None
        out.append(number)
    return out


def normalise_epoch_list(value: object, *, key: str, path: Path) -> list[int] | None:
    """Normalise epoch list."""
    out = normalise_int_list(value, key=key, path=path)
    if out is None:
        return None
    for number in out:
        if number > MAX_REASONABLE_STATE_EPOCH:
            log.error("State candidate %s has impossible %s epoch item %r; ignoring", path, key, number)
            return None
    return out


def normalise_string_map(value: object, *, key: str, path: Path) -> dict[str, str] | None:
    """Normalise string map."""
    if not isinstance(value, dict):
        log.error("State candidate %s has invalid %s type %s; ignoring", path, key, type(value).__name__)
        return None
    return {str(k): str(v) for k, v in value.items() if v is not None}


def normalise_int_map(value: object, *, key: str, path: Path) -> dict[str, int] | None:
    """Normalise int map."""
    if not isinstance(value, dict):
        log.error("State candidate %s has invalid %s type %s; ignoring", path, key, type(value).__name__)
        return None
    out: dict[str, int] = {}
    for item_key, item_value in value.items():
        number = normalise_state_int(item_value, key=f"{key}.{item_key}", path=path)
        if number is None:
            return None
        out[str(item_key)] = number
    return out


def normalise_record_map(value: object, *, key: str, path: Path) -> dict[str, dict] | None:
    """Normalise record map."""
    if not isinstance(value, dict):
        log.error("State candidate %s has invalid %s type %s; ignoring", path, key, type(value).__name__)
        return None
    out: dict[str, dict] = {}
    for item_key, item_value in value.items():
        if not isinstance(item_value, dict):
            log.error(
                "State candidate %s has invalid %s.%s type %s; ignoring",
                path,
                key,
                item_key,
                type(item_value).__name__,
            )
            return None
        out[str(item_key)] = dict(item_value)
    return out


def quote_repeated_cursor_suppression_record(
    post_id: object,
    value: object,
    *,
    current_epoch: int,
    allow_expired: bool = False,
) -> dict[str, object] | None:
    """Return one canonical exact-cursor suppression record when usable."""
    if (
        type(post_id) is not str
        or bounded_tweet_id_value(post_id) is None
        or not isinstance(value, dict)
        or set(value)
        != {"cursor_sha256", "detected_epoch", "retry_after_epoch"}
    ):
        return None
    cursor_sha256 = value.get("cursor_sha256")
    detected_epoch = value.get("detected_epoch")
    retry_after_epoch = value.get("retry_after_epoch")
    if (
        type(cursor_sha256) is not str
        or re.fullmatch(r"[0-9a-f]{64}", cursor_sha256) is None
        or type(detected_epoch) is not int
        or detected_epoch < 0
        or detected_epoch > current_epoch
        or detected_epoch > MAX_REASONABLE_STATE_EPOCH
        or type(retry_after_epoch) is not int
        or retry_after_epoch
        != detected_epoch + QUOTE_REPEATED_CURSOR_BACKOFF_SECONDS
        or retry_after_epoch > MAX_REASONABLE_STATE_EPOCH
        or (not allow_expired and retry_after_epoch <= current_epoch)
    ):
        return None
    return {
        "cursor_sha256": cursor_sha256,
        "detected_epoch": detected_epoch,
        "retry_after_epoch": retry_after_epoch,
    }


def normalise_quote_repeated_cursor_suppressions(
    value: object,
    *,
    current_epoch: int | None = None,
) -> tuple[dict[str, dict[str, object]], int]:
    """Discard malformed, expired, and excess quote-cursor suppressions."""
    if current_epoch is None:
        current_epoch = now_epoch()
    if not isinstance(value, dict):
        return {}, 1

    retained: list[tuple[str, dict[str, object]]] = []
    for post_id, record in value.items():
        canonical = quote_repeated_cursor_suppression_record(
            post_id,
            record,
            current_epoch=current_epoch,
        )
        if canonical is not None:
            retained.append((post_id, canonical))

    retained.sort(
        key=lambda item: (
            int(item[1]["detected_epoch"]),
            int(item[1]["retry_after_epoch"]),
            item[0],
        ),
        reverse=True,
    )
    retained = retained[:QUOTE_REPEATED_CURSOR_SUPPRESSION_MAX_ENTRIES]
    normalised = dict(retained)
    discarded = max(0, len(value) - len(normalised))
    if normalised != value and discarded == 0:
        discarded = 1
    return normalised, discarded


def completed_mention_watermark_covers_target(state: dict, target_id: str) -> bool:
    """Return whether a completed mention traversal prevents refetching one target."""
    target_id = str(target_id)
    watermark = str(state.get("last_seen_mention_id") or "")
    pending = state.get("mention_pending_candidates")
    if (
        not target_id.isdigit()
        or not watermark.isdigit()
        or not isinstance(pending, dict)
        or target_id in pending
    ):
        return False
    return int(target_id) <= int(watermark)


def prune_completed_mention_quarantine_evaluations(state: dict) -> int:
    """Drop unsafe legacy or watermark-covered local quarantine skips."""
    records = state.get("reply_evaluation_records")
    if not isinstance(records, dict):
        return 0
    removable = {
        str(target_id)
        for target_id, record in records.items()
        if isinstance(record, dict)
        and record.get("lane") == "mention"
        and record.get("outcome") == "no_reply"
        and record.get("reason") == "author_evaluation_quarantine"
        and (
            record.get("evidence_policy")
            != AUTHOR_EVALUATION_QUARANTINE_EVIDENCE_POLICY
            or completed_mention_watermark_covers_target(state, str(target_id))
        )
    }
    if not removable:
        return 0
    state["reply_evaluation_records"] = {
        str(target_id): record
        for target_id, record in records.items()
        if str(target_id) not in removable
    }
    log.info(
        "Retired %s legacy or completed-watermark mention quarantine evaluations",
        len(removable),
    )
    return len(removable)


def prune_reply_evaluation_records(
    state: dict,
    *,
    current_epoch: int | None = None,
) -> None:
    """Prune old terminal evaluations while preserving recent replay protection."""
    prune_completed_mention_quarantine_evaluations(state)
    records = state.get("reply_evaluation_records")
    if not isinstance(records, dict):
        return
    if current_epoch is None:
        current_epoch = now_epoch()
    current_epoch = int(current_epoch)
    cutoff = current_epoch - REPLY_EVALUATION_MIN_RETENTION_SECONDS

    def evaluated_epoch(item: tuple[str, dict]) -> int | None:
        value = item[1].get("evaluated_epoch")
        if type(value) is not int or value < 0 or value > MAX_REASONABLE_STATE_EPOCH:
            return None
        return value

    items = [
        (str(target_id), dict(record))
        for target_id, record in records.items()
        if isinstance(record, dict)
    ]
    protected = [
        item
        for item in items
        if evaluated_epoch(item) is None or evaluated_epoch(item) > cutoff
    ]
    older = [
        item
        for item in items
        if evaluated_epoch(item) is not None and evaluated_epoch(item) <= cutoff
    ]

    def sort_key(item: tuple[str, dict]) -> tuple[int, str]:
        epoch = evaluated_epoch(item)
        return (epoch if epoch is not None else MAX_REASONABLE_STATE_EPOCH + 1, item[0])

    protected.sort(key=sort_key)
    older.sort(key=sort_key)
    protected_overflow = max(0, len(protected) - REPLY_EVALUATION_MAX_RECORDS)
    if protected_overflow:
        evictable_quarantine = [
            item
            for item in protected
            if evaluated_epoch(item) is not None
            and item[1].get("lane") == "mention"
            and item[1].get("outcome") == "no_reply"
            and item[1].get("reason") == "author_evaluation_quarantine"
        ]
        evicted_ids = {
            target_id
            for target_id, _record in evictable_quarantine[:protected_overflow]
        }
        if evicted_ids:
            protected = [
                item for item in protected if item[0] not in evicted_ids
            ]
            log.warning(
                "Pruned %s oldest recent mention quarantine evaluations to bound "
                "reply-evaluation state; an incomplete traversal may refetch them",
                len(evicted_ids),
            )
    if len(protected) > REPLY_EVALUATION_MAX_RECORDS:
        retained = protected
        log.warning(
            "Recent or conservatively protected reply evaluations exceed nominal cap: "
            "protected=%s cap=%s; retaining all protected records",
            len(protected),
            REPLY_EVALUATION_MAX_RECORDS,
        )
    else:
        available_older_slots = max(0, REPLY_EVALUATION_MAX_RECORDS - len(protected))
        retained = protected + older[-available_older_slots:] if available_older_slots else protected
    retained.sort(key=sort_key)
    state["reply_evaluation_records"] = {
        target_id: record for target_id, record in retained
    }
    removed = len(records) - len(retained)
    if removed:
        log.info(
            "Pruned %s reply evaluation records; retained=%s cap=%s",
            removed,
            len(retained),
            REPLY_EVALUATION_MAX_RECORDS,
        )


def author_no_reply_epoch_limit() -> int:
    """Return retention sized from the effective runtime quarantine threshold."""
    return max(100, int(AUTHOR_NO_REPLY_QUARANTINE_THRESHOLD) * 4)


def prune_author_evaluation_quarantines(
    state: dict,
    *,
    current_epoch: int | None = None,
) -> bool:
    """Expire quarantines and discard author strikes outside the live window."""
    records = state.get("author_evaluation_quarantines")
    if not isinstance(records, dict):
        state["author_evaluation_quarantines"] = {}
        return True
    current = now_epoch() if current_epoch is None else int(current_epoch)
    cutoff = current - AUTHOR_NO_REPLY_QUARANTINE_WINDOW_SECONDS
    retained: dict[str, dict[str, object]] = {}
    changed = False
    for author_id, raw_record in records.items():
        if not isinstance(raw_record, dict):
            changed = True
            continue
        if (
            raw_record.get("evidence_policy")
            != AUTHOR_EVALUATION_QUARANTINE_EVIDENCE_POLICY
        ):
            changed = True
            continue
        explicit_epoch = raw_record.get(
            "latest_explicit_spam_or_abuse_epoch"
        )
        if (
            type(explicit_epoch) is not int
            or explicit_epoch < 0
            or explicit_epoch > MAX_REASONABLE_STATE_EPOCH
        ):
            changed = True
            continue
        recent = [
            int(epoch)
            for epoch in raw_record.get("recent_no_reply_epochs", [])
            if type(epoch) is int and cutoff < epoch <= current
        ]
        recent.sort()
        recent = recent[-author_no_reply_epoch_limit():]
        until = int(raw_record.get("quarantine_until_epoch", 0) or 0)
        updated = int(raw_record.get("last_updated_epoch", 0) or 0)
        if until and until <= current:
            log_event(
                "author_evaluation_quarantine_expired",
                author_id=str(author_id),
                quarantine_until_epoch=until,
                expired_epoch=current,
            )
            until = 0
            recent = []
            explicit_epoch = 0
            updated = current
            changed = True
        if until > current or recent:
            record = {
                "recent_no_reply_epochs": recent,
                "quarantine_until_epoch": until,
                "last_updated_epoch": updated,
                "latest_explicit_spam_or_abuse_epoch": explicit_epoch,
                "evidence_policy": AUTHOR_EVALUATION_QUARANTINE_EVIDENCE_POLICY,
            }
            retained[str(author_id)] = record
            if record != raw_record or str(author_id) != author_id:
                changed = True
        else:
            changed = True
    if retained != records:
        state["author_evaluation_quarantines"] = retained
        changed = True
    return changed


def active_author_evaluation_quarantine(
    state: dict,
    author_id: str,
    *,
    current_epoch: int | None = None,
) -> dict | None:
    """Return an active mention-lane author quarantine, expiring old state first."""
    current = now_epoch() if current_epoch is None else int(current_epoch)
    prune_author_evaluation_quarantines(state, current_epoch=current)
    records = state.get("author_evaluation_quarantines", {})
    record = records.get(str(author_id)) if isinstance(records, dict) else None
    if (
        isinstance(record, dict)
        and int(record.get("quarantine_until_epoch", 0) or 0) > current
    ):
        return record
    return None


def record_qualifying_author_no_reply(
    state: dict,
    author_id: str,
    *,
    current_epoch: int | None = None,
    explicit_spam_or_abuse: bool = True,
) -> bool:
    """Add one final majority-resolvable no-reply strike for an author."""
    author_id = str(author_id)
    if not author_id or not author_id.isdigit():
        return False
    current = now_epoch() if current_epoch is None else int(current_epoch)
    prune_author_evaluation_quarantines(state, current_epoch=current)
    records = state.get("author_evaluation_quarantines", {})
    if not isinstance(records, dict):
        records = {}
    records = dict(records)
    existing = records.get(author_id, {})
    if not isinstance(existing, dict):
        existing = {}
    cutoff = current - AUTHOR_NO_REPLY_QUARANTINE_WINDOW_SECONDS
    recent = [
        int(epoch)
        for epoch in existing.get("recent_no_reply_epochs", [])
        if type(epoch) is int and cutoff < epoch <= current
    ]
    explicit_epoch = existing.get("latest_explicit_spam_or_abuse_epoch", 0)
    if explicit_spam_or_abuse is True:
        explicit_epoch = current
    recent.append(current)
    recent.sort()
    recent = recent[-author_no_reply_epoch_limit():]
    until = int(existing.get("quarantine_until_epoch", 0) or 0)
    started = False
    if until <= current and len(recent) >= AUTHOR_NO_REPLY_QUARANTINE_THRESHOLD:
        until = current + AUTHOR_NO_REPLY_QUARANTINE_SECONDS
        started = True
        log_event(
            "author_evaluation_quarantine_started",
            author_id=author_id,
            strike_count=len(recent),
            threshold=AUTHOR_NO_REPLY_QUARANTINE_THRESHOLD,
            window_seconds=AUTHOR_NO_REPLY_QUARANTINE_WINDOW_SECONDS,
            quarantine_seconds=AUTHOR_NO_REPLY_QUARANTINE_SECONDS,
            quarantine_until_epoch=until,
        )
    records[author_id] = {
        "recent_no_reply_epochs": recent,
        "quarantine_until_epoch": until,
        "last_updated_epoch": current,
        "latest_explicit_spam_or_abuse_epoch": explicit_epoch,
        "evidence_policy": AUTHOR_EVALUATION_QUARANTINE_EVIDENCE_POLICY,
    }
    state["author_evaluation_quarantines"] = records
    return started


def clear_author_evaluation_quarantine_history(state: dict, author_id: str) -> bool:
    """Clear prior strikes when a mention receives a fully approved reply."""
    records = state.get("author_evaluation_quarantines")
    if not isinstance(records, dict) or str(author_id) not in records:
        return False
    records = dict(records)
    records.pop(str(author_id), None)
    state["author_evaluation_quarantines"] = records
    return True


def normalise_tweet_cache_entry(tweet_id: object, entry: dict, *, path: Path) -> dict[str, object] | None:
    """Normalise tweet cache entry."""
    cached_epoch = normalise_state_epoch(entry.get("cached_epoch", 0), key=f"tweet_cache.{tweet_id}.cached_epoch", path=path)
    if cached_epoch is None:
        return None

    referenced_tweets = entry.get("referenced_tweets", [])
    if not isinstance(referenced_tweets, list):
        log.error(
            "State candidate %s has invalid tweet_cache.%s.referenced_tweets type %s; ignoring",
            path,
            tweet_id,
            type(referenced_tweets).__name__,
        )
        return None
    normalized_refs: list[dict[str, str]] = []
    for index, ref in enumerate(referenced_tweets):
        if not isinstance(ref, dict):
            log.error(
                "State candidate %s has invalid tweet_cache.%s.referenced_tweets[%d] type %s; ignoring",
                path,
                tweet_id,
                index,
                type(ref).__name__,
            )
            return None
        normalized_ref: dict[str, str] = {}
        if ref.get("type") is not None:
            normalized_ref["type"] = str(ref.get("type"))
        if ref.get("id") is not None:
            normalized_ref["id"] = str(ref.get("id"))
        for key, ref_value in ref.items():
            if key in {"type", "id"} or ref_value is None:
                continue
            normalized_ref[str(key)] = str(ref_value)
        normalized_refs.append(normalized_ref)

    entry_id = entry.get("id")
    normalized_id = str(entry_id if entry_id is not None else tweet_id)
    conversation_id = entry.get("conversation_id")
    normalized_entry: dict[str, object] = {
        "id": normalized_id,
        "author_id": str(entry.get("author_id") or ""),
        "conversation_id": str(conversation_id if conversation_id is not None else normalized_id),
        "created_at": str(entry.get("created_at") or ""),
        "referenced_tweets": normalized_refs,
        "text": str(entry.get("text") or ""),
        "cached_epoch": cached_epoch,
    }
    if entry.get("image_summary") is not None:
        normalized_entry["image_summary"] = str(entry.get("image_summary"))
    if entry.get("post_type") is not None:
        normalized_entry["post_type"] = str(entry.get("post_type"))
    return normalized_entry


def normalise_tweet_cache(value: object, *, path: Path) -> dict[str, dict] | None:
    """Normalise tweet cache."""
    if not isinstance(value, dict):
        log.error("State candidate %s has invalid tweet_cache type %s; ignoring", path, type(value).__name__)
        return None
    out: dict[str, dict] = {}
    for tweet_id, entry in value.items():
        if not isinstance(entry, dict):
            log.error(
                "State candidate %s has invalid tweet_cache.%s type %s; ignoring",
                path,
                tweet_id,
                type(entry).__name__,
            )
            return None
        normalized_entry = normalise_tweet_cache_entry(tweet_id, entry, path=path)
        if normalized_entry is None:
            return None
        out[str(tweet_id)] = normalized_entry
    return out


def normalise_mention_pagination(value: object, *, path: Path) -> dict[str, str] | None:
    """Normalise mention pagination."""
    if not isinstance(value, dict):
        log.error("State candidate %s has invalid mention_pagination type %s; ignoring", path, type(value).__name__)
        return None
    if not value:
        return {}
    if not set(value).issubset({"base_since_id", "next_token"}):
        log.error(
            "State candidate %s has unknown mention_pagination fields; ignoring",
            path,
        )
        return None
    base_since_id = value.get("base_since_id", "")
    next_token = value.get("next_token")
    if (
        not isinstance(base_since_id, str)
        or bounded_tweet_id_value(base_since_id, allow_empty=True) is None
    ):
        log.error(
            "State candidate %s has invalid mention pagination base; ignoring",
            path,
        )
        return None
    candidate = {
        "base_since_id": base_since_id,
        "next_token": next_token,
    }
    if not mention_pagination_provenance_is_valid(candidate):
        log.error(
            "State candidate %s has invalid mention pagination token; ignoring",
            path,
        )
        return None
    return candidate


def normalise_mention_backlog_reset_guard(
    value: object,
    *,
    path: Path,
) -> dict[str, object] | None:
    """Validate the watermark guard installed when mention provenance is reset."""
    if not isinstance(value, dict):
        log.error(
            "State candidate %s has invalid mention_backlog_reset_guard type %s; ignoring",
            path,
            type(value).__name__,
        )
        return None
    if not value:
        return {}
    if set(value) != {"base_since_id", "head_traversal_started"}:
        log.error(
            "State candidate %s has invalid mention_backlog_reset_guard fields; ignoring",
            path,
        )
        return None
    base_since_id = value.get("base_since_id")
    head_traversal_started = value.get("head_traversal_started")
    if (
        not isinstance(base_since_id, str)
        or bounded_tweet_id_value(base_since_id, allow_empty=True) is None
        or type(head_traversal_started) is not bool
    ):
        log.error(
            "State candidate %s has invalid mention_backlog_reset_guard values; ignoring",
            path,
        )
        return None
    return {
        "base_since_id": base_since_id,
        "head_traversal_started": head_traversal_started,
    }


def active_mention_backlog_reset_guard(state: dict) -> dict[str, object] | None:
    """Return the reset guard only while it is bound to the current watermark."""
    guard = state.get("mention_backlog_reset_guard")
    if (
        not isinstance(guard, dict)
        or set(guard) != {"base_since_id", "head_traversal_started"}
        or not isinstance(guard.get("base_since_id"), str)
        or type(guard.get("head_traversal_started")) is not bool
        or str(guard["base_since_id"])
        != str(state.get("last_seen_mention_id") or "")
    ):
        return None
    return guard


def normalise_mention_backlog(
    value: object,
    *,
    path: Path,
    reset_token_overflow: bool = False,
) -> dict | None:
    """Validate the durable state for one incomplete mention traversal."""
    if not isinstance(value, dict):
        log.error("State candidate %s has invalid mention_backlog type %s; ignoring", path, type(value).__name__)
        return None
    if not value:
        return {}
    expected = {
        "since_id",
        "next_token",
        "highest_mention_id",
        "pages_completed",
        "started_epoch",
        "seen_tokens",
        "announced",
    }
    if set(value) != expected:
        log.error("State candidate %s has invalid mention_backlog fields; ignoring", path)
        return None
    since_id = value.get("since_id")
    next_token = value.get("next_token")
    highest_id = value.get("highest_mention_id")
    pages = value.get("pages_completed")
    started = value.get("started_epoch")
    seen_tokens = value.get("seen_tokens")
    announced = value.get("announced")
    if (
        not isinstance(since_id, str)
        or bounded_tweet_id_value(since_id, allow_empty=True) is None
    ):
        return None
    if (
        not isinstance(next_token, str)
        or next_token != next_token.strip()
        or any(character.isspace() for character in next_token)
    ):
        return None
    if (
        not isinstance(highest_id, str)
        or bounded_tweet_id_value(highest_id, allow_empty=True) is None
    ):
        return None
    if type(pages) is not int or pages < 0:
        return None
    if type(started) is not int or started < 0 or started > MAX_REASONABLE_STATE_EPOCH:
        return None
    if (
        not isinstance(seen_tokens, list)
        or any(
            not isinstance(token, str)
            or not token
            or token != token.strip()
            or any(character.isspace() for character in token)
            for token in seen_tokens
        )
        or len(set(seen_tokens)) != len(seen_tokens)
    ):
        return None
    if type(announced) is not bool:
        return None
    if len(seen_tokens) > MENTION_BACKLOG_CONTINUATION_TOKEN_LIMIT:
        return {} if reset_token_overflow else None
    return {
        "since_id": since_id,
        "next_token": next_token,
        "highest_mention_id": highest_id,
        "pages_completed": pages,
        "started_epoch": started,
        "seen_tokens": list(seen_tokens),
        "announced": announced,
    }


def canonical_mention_pending_candidates(
    value: object,
    *,
    path: Path,
) -> dict[str, dict] | None:
    """Validate exact, bounded identities for the durable mention queue."""
    if not isinstance(value, dict):
        log.error(
            "State candidate %s has invalid mention_pending_candidates type %s; ignoring",
            path,
            type(value).__name__,
        )
        return None
    canonical: dict[str, dict] = {}
    seen_ids: set[int] = set()
    for map_key, candidate in value.items():
        embedded_id = candidate.get("id") if isinstance(candidate, dict) else None
        map_id = bounded_tweet_id_value(map_key)
        candidate_id = bounded_tweet_id_value(embedded_id)
        if (
            type(map_key) is not str
            or not isinstance(candidate, dict)
            or type(embedded_id) is not str
            or map_id is None
            or candidate_id is None
            or map_key != embedded_id
        ):
            log.error(
                "State candidate %s has a pending mention with invalid or mismatched identity; ignoring",
                path,
            )
            return None
        if candidate_id in seen_ids:
            log.error(
                "State candidate %s has duplicate pending mention identity; ignoring",
                path,
            )
            return None
        seen_ids.add(candidate_id)
        canonical[map_key] = dict(candidate)
    return canonical


def _emit_mention_authority_recovery(
    recovery: dict[str, object],
    *,
    path: Path,
    recovery_events: list[dict[str, object]] | None,
) -> None:
    if recovery_events is not None:
        recovery_events.append(recovery)
        return
    log.warning(
        "Resetting unsafe mention candidate authority reason=%s path=%s; "
        "watermark remains unchanged and %s pending candidate(s) were discarded",
        recovery.get("reason"),
        path,
        recovery.get("discarded_candidates", 0),
    )
    log_event("mention_backlog_reset", **recovery)


def _reset_mention_candidate_authority(
    state: dict,
    *,
    watermark: str,
) -> None:
    """Clear one unsafe traversal generation and require a head traversal."""
    state["mention_backlog"] = {}
    state["mention_pagination"] = {}
    state["mention_pending_candidates"] = {}
    state["mention_backlog_reset_guard"] = {
        "base_since_id": watermark,
        "head_traversal_started": False,
    }


def validate_pending_mention_candidate_authority(
    state: dict,
    *,
    path: Path,
    recover_pending_identity: bool,
    recovery_events: list[dict[str, object]] | None = None,
) -> tuple[bool, bool]:
    """Canonicalise the queue and reject candidates without coherent provenance.

    The boolean pair is ``(usable, changed)``.  A strict state-loader pass uses
    ``recover_pending_identity=False`` so a usable backup wins over recovery of
    a corrupt primary.  Runtime queue and receipt callers recover fail-closed.
    """
    raw_watermark = state.get("last_seen_mention_id")
    watermark = "" if raw_watermark in (None, "") else raw_watermark
    if (
        type(watermark) is not str
        or bounded_tweet_id_value(watermark, allow_empty=True) is None
    ):
        log.error(
            "State candidate %s has no bounded mention watermark for pending authority",
            path,
        )
        return False, False
    watermark_value = bounded_tweet_id_value(watermark, allow_empty=True)
    assert watermark_value is not None

    raw_pending = state.get("mention_pending_candidates", {})
    pending = canonical_mention_pending_candidates(raw_pending, path=path)
    if pending is None:
        if not recover_pending_identity:
            return False, False
        discarded = len(raw_pending) if isinstance(raw_pending, dict) else 0
        _reset_mention_candidate_authority(state, watermark=watermark)
        _emit_mention_authority_recovery(
            {
                "reason": "invalid_pending_candidate_identity",
                "since_id": watermark or None,
                "discarded_candidates": discarded,
            },
            path=path,
            recovery_events=recovery_events,
        )
        return True, True

    changed = pending != raw_pending
    replied_ids = {str(value) for value in state.get("replied_to_ids", [])}
    deduplicated = {
        mention_id: candidate
        for mention_id, candidate in pending.items()
        if mention_id not in replied_ids
        and terminal_reply_evaluation(state, mention_id) is None
    }
    if deduplicated != pending:
        log.info(
            "Disposed of %s already handled durable mention candidate(s) without provider work",
            len(pending) - len(deduplicated),
        )
        pending = deduplicated
        changed = True
    if pending != raw_pending:
        state["mention_pending_candidates"] = pending

    raw_backlog = state.get("mention_backlog", {})
    raw_pagination = state.get("mention_pagination", {})
    raw_guard = state.get("mention_backlog_reset_guard", {})
    authority_failure = ""

    backlog = (
        normalise_mention_backlog(raw_backlog, path=path)
        if isinstance(raw_backlog, dict)
        else None
    )
    pagination = (
        normalise_mention_pagination(raw_pagination, path=path)
        if isinstance(raw_pagination, dict)
        else None
    )
    guard = (
        normalise_mention_backlog_reset_guard(raw_guard, path=path)
        if isinstance(raw_guard, dict)
        else None
    )
    if backlog is None:
        authority_failure = "invalid_backlog"
    elif pagination is None:
        authority_failure = "invalid_pagination"
    elif guard is None:
        authority_failure = "invalid_reset_guard"
    elif guard and active_mention_backlog_reset_guard(state) is None:
        authority_failure = "reset_guard_base_mismatch"

    if not authority_failure and backlog:
        base = backlog["since_id"]
        highest = backlog["highest_mention_id"]
        next_token = backlog["next_token"]
        base_value = bounded_tweet_id_value(base, allow_empty=True)
        highest_value = bounded_tweet_id_value(highest, allow_empty=True)
        if base_value is None or highest_value is None:
            authority_failure = "unbounded_backlog_identity"
        elif base != watermark:
            authority_failure = "backlog_base_mismatch"
        elif highest_value < watermark_value:
            authority_failure = "backlog_highest_before_watermark"
        elif next_token:
            expected_pagination = {
                "base_since_id": base,
                "next_token": next_token,
            }
            if int(backlog["pages_completed"]) <= 0:
                authority_failure = "continuation_without_completed_page"
            elif pagination != expected_pagination:
                authority_failure = "backlog_pagination_mismatch"
            elif pending and not highest:
                authority_failure = "pending_without_highest_identity"
            elif any(
                (candidate_value := bounded_tweet_id_value(mention_id)) is None
                or candidate_value <= watermark_value
                or candidate_value > highest_value
                for mention_id in pending
            ):
                authority_failure = "pending_outside_active_page_range"
        elif int(backlog["pages_completed"]) != 0:
            authority_failure = "completed_backlog_without_continuation"
        elif highest != watermark:
            authority_failure = "head_backlog_highest_mismatch"
        elif pagination:
            authority_failure = "pagination_without_backlog_continuation"
        elif pending:
            authority_failure = "pending_before_first_completed_page"

    if not authority_failure and not backlog and pagination:
        pagination_base = pagination["base_since_id"]
        if bounded_tweet_id_value(pagination_base, allow_empty=True) is None:
            authority_failure = "unbounded_pagination_base"
        elif pagination_base != watermark:
            authority_failure = "pagination_base_mismatch"
        else:
            # A cursor can recover the unseen tail, but it cannot prove page
            # ownership or authorize watermark advancement.  Always bind it
            # to a false reset guard and require a later head traversal.
            discarded = len(pending)
            state["mention_pending_candidates"] = {}
            state["mention_backlog_reset_guard"] = {
                "base_since_id": watermark,
                "head_traversal_started": False,
            }
            if pending or guard != state["mention_backlog_reset_guard"]:
                _emit_mention_authority_recovery(
                    {
                        "reason": "pagination_without_page_ownership",
                        "since_id": watermark or None,
                        "discarded_candidates": discarded,
                    },
                    path=path,
                    recovery_events=recovery_events,
                )
                return True, True

    if (
        not authority_failure
        and not backlog
        and not pagination
        and guard
        and guard["head_traversal_started"]
    ):
        # A true guard without its owning head backlog records an interrupted
        # traversal.  A false guard may legitimately own candidates fetched
        # from a restored tail cursor whose completion deferred the watermark.
        discarded = len(pending)
        state["mention_pending_candidates"] = {}
        state["mention_backlog_reset_guard"] = {
            "base_since_id": watermark,
            "head_traversal_started": False,
        }
        _emit_mention_authority_recovery(
            {
                "reason": "head_traversal_ownership_missing",
                "since_id": watermark or None,
                "discarded_candidates": discarded,
            },
            path=path,
            recovery_events=recovery_events,
        )
        return True, True

    if authority_failure:
        discarded = len(pending)
        _reset_mention_candidate_authority(state, watermark=watermark)
        _emit_mention_authority_recovery(
            {
                "reason": "stale_pending_candidate_authority",
                "authority_failure": authority_failure,
                "since_id": watermark or None,
                "discarded_candidates": discarded,
            },
            path=path,
            recovery_events=recovery_events,
        )
        return True, True

    if not backlog and not pagination and pending and not guard:
        covered = {
            mention_id: candidate
            for mention_id, candidate in pending.items()
            if (
                (candidate_value := bounded_tweet_id_value(mention_id))
                is not None
                and candidate_value <= watermark_value
            )
        }
        discarded = len(pending) - len(covered)
        if discarded:
            state["mention_pending_candidates"] = covered
            state["mention_backlog_reset_guard"] = {
                "base_since_id": watermark,
                "head_traversal_started": False,
            }
            _emit_mention_authority_recovery(
                {
                    "reason": "orphaned_pending_candidates",
                    "since_id": watermark or None,
                    "discarded_candidates": discarded,
                },
                path=path,
                recovery_events=recovery_events,
            )
            return True, True

    return True, changed


def mention_pagination_has_canonical_page_ownership(
    state: dict,
    pagination: object,
    *,
    target_id: str,
) -> bool:
    """Return whether canonical state owns the page bound into a receipt."""
    if not mention_pagination_provenance_is_valid(pagination):
        return False
    if state.get("mention_pagination") != pagination:
        return False
    backlog = state.get("mention_backlog")
    if not isinstance(backlog, dict) or not backlog:
        return False
    normalised = normalise_mention_backlog(backlog, path=STATE_FILE)
    if normalised is None or normalised != backlog:
        return False
    watermark = str(state.get("last_seen_mention_id") or "")
    base = str(normalised.get("since_id") or "")
    highest = str(normalised.get("highest_mention_id") or "")
    base_value = bounded_tweet_id_value(base, allow_empty=True)
    highest_value = bounded_tweet_id_value(highest)
    target_value = bounded_tweet_id_value(target_id)
    return bool(
        base == watermark == pagination["base_since_id"]
        and normalised.get("next_token") == pagination["next_token"]
        and int(normalised.get("pages_completed", 0)) > 0
        and base_value is not None
        and highest_value is not None
        and target_value is not None
        and base_value < target_value <= highest_value
    )


def normalise_author_evaluation_quarantines(value: object, *, path: Path) -> dict | None:
    """Validate compact per-author no-reply strike and quarantine records."""
    if not isinstance(value, dict):
        log.error(
            "State candidate %s has invalid author_evaluation_quarantines type %s; ignoring",
            path,
            type(value).__name__,
        )
        return None
    result: dict[str, dict[str, object]] = {}
    legacy_fields = {
        "recent_no_reply_epochs",
        "quarantine_until_epoch",
        "last_updated_epoch",
    }
    previous_policy_fields = legacy_fields | {"evidence_policy"}
    current_fields = previous_policy_fields | {
        "latest_explicit_spam_or_abuse_epoch"
    }
    for raw_author_id, raw_record in value.items():
        author_id = str(raw_author_id)
        if not author_id.isdigit() or not isinstance(raw_record, dict):
            return None
        record_fields = set(raw_record)
        if record_fields == legacy_fields:
            log.warning(
                "Discarding legacy broad author-evaluation quarantine for author_id=%s from %s",
                author_id,
                path,
            )
            continue
        if (
            record_fields != previous_policy_fields
            and record_fields != current_fields
        ):
            return None
        evidence_policy = raw_record.get("evidence_policy")
        is_legacy_policy = (
            record_fields == previous_policy_fields
            and evidence_policy
            == AUTHOR_EVALUATION_QUARANTINE_LEGACY_EVIDENCE_POLICY
        )
        is_seeded_policy = (
            record_fields == current_fields
            and evidence_policy
            == AUTHOR_EVALUATION_QUARANTINE_SEEDED_EVIDENCE_POLICY
        )
        is_current_policy = (
            record_fields == current_fields
            and evidence_policy
            == AUTHOR_EVALUATION_QUARANTINE_EVIDENCE_POLICY
        )
        if not (is_legacy_policy or is_seeded_policy or is_current_policy):
            return None
        timestamps = raw_record.get("recent_no_reply_epochs")
        until = raw_record.get("quarantine_until_epoch")
        updated = raw_record.get("last_updated_epoch")
        if (
            not isinstance(timestamps, list)
            or any(
                type(timestamp) is not int
                or timestamp < 0
                or timestamp > MAX_REASONABLE_STATE_EPOCH
                for timestamp in timestamps
            )
            or len(timestamps) > author_no_reply_epoch_limit()
            or timestamps != sorted(timestamps)
        ):
            return None
        if (
            type(until) is not int
            or until < 0
            or until > MAX_REASONABLE_STATE_EPOCH
            or type(updated) is not int
            or updated < 0
            or updated > MAX_REASONABLE_STATE_EPOCH
        ):
            return None
        if is_legacy_policy:
            if not timestamps:
                if not until:
                    log.warning(
                        "Discarding empty prior-policy author-evaluation history "
                        "for author_id=%s from %s",
                        author_id,
                        path,
                    )
                    continue
                # A v1 quarantine can outlive its six-hour strike history.
                # Preserve that active-until value without manufacturing an
                # explicit-spam timestamp that the old record did not store.
                explicit_epoch = 0
            else:
                explicit_epoch = timestamps[-1]
            log.info(
                "Migrating prior explicit-spam author-evaluation history "
                "for author_id=%s from %s",
                author_id,
                path,
            )
        else:
            explicit_epoch = raw_record.get(
                "latest_explicit_spam_or_abuse_epoch"
            )
            if (
                type(explicit_epoch) is not int
                or explicit_epoch < 0
                or explicit_epoch > MAX_REASONABLE_STATE_EPOCH
                or explicit_epoch > updated
            ):
                return None
            if (
                is_seeded_policy
                and not until
                and explicit_epoch not in timestamps
            ):
                return None
            if is_seeded_policy:
                log.info(
                    "Migrating seeded-corroboration author-evaluation history "
                    "for author_id=%s from %s",
                    author_id,
                    path,
                )
        result[author_id] = {
            "recent_no_reply_epochs": list(timestamps),
            "quarantine_until_epoch": until,
            "last_updated_epoch": updated,
            "latest_explicit_spam_or_abuse_epoch": explicit_epoch,
            "evidence_policy": AUTHOR_EVALUATION_QUARANTINE_EVIDENCE_POLICY,
        }
    return result


def normalise_optional_scalar(value: object, *, key: str, path: Path) -> str | None:
    """Normalise optional scalar."""
    if value is None:
        return ""
    if isinstance(value, (str, int)):
        return str(value)
    log.error("State candidate %s has invalid %s type %s; ignoring", path, key, type(value).__name__)
    return None


def normalise_optional_numeric_id(value: object, *, key: str, path: Path) -> str | None:
    """Normalise optional numeric ID."""
    if value in (None, ""):
        return ""
    text = str(value)
    if bounded_tweet_id_value(text) is not None:
        return text
    log.error("State candidate %s has invalid %s value %r; ignoring", path, key, value)
    return None


def validate_meme_schedule_state(state: dict, *, path: Path) -> bool:
    """Validate meme schedule state."""
    next_epoch = int(state.get("next_meme_post_epoch", 0) or 0)
    if not next_epoch:
        return True
    if not valid_receipt_epoch(next_epoch):
        log.error("State candidate %s has receipt-incompatible active meme target epoch %s; ignoring", path, next_epoch)
        return False

    mode = str(state.get("next_meme_schedule_mode", "") or "")
    schedule_date = str(state.get("next_meme_schedule_date", "") or "")
    anchor_epoch = int(state.get("meme_anchor_quote_post_epoch", 0) or 0)

    if mode not in MEME_SCHEDULE_MODES or not mode:
        log.error("State candidate %s has invalid meme schedule mode %r; ignoring", path, mode)
        return False

    if mode == "after_first_quote_after_midday":
        if anchor_epoch <= 0:
            log.error("State candidate %s has quote-anchored meme schedule without anchor; ignoring", path)
            return False
        if not valid_receipt_epoch(anchor_epoch):
            log.error("State candidate %s has receipt-incompatible meme anchor epoch %s; ignoring", path, anchor_epoch)
            return False
        if next_epoch <= anchor_epoch:
            log.error("State candidate %s has quote-anchored meme target not after anchor; ignoring", path)
            return False
        expected_date = safe_bound_schedule_date_str(
            anchor_epoch,
            MAIN_POST_SCHEDULE_TIMEZONE,
        )
        if not expected_date or schedule_date != expected_date:
            log.error(
                "State candidate %s has quote-anchored meme schedule_date=%r expected=%r; ignoring",
                path,
                schedule_date,
                expected_date,
            )
            return False
        return True

    if anchor_epoch:
        log.error("State candidate %s has non-quote meme schedule with stale quote anchor; ignoring", path)
        return False
    expected_date = safe_bound_schedule_date_str(
        next_epoch,
        MAIN_POST_SCHEDULE_TIMEZONE,
    )
    if not expected_date or schedule_date != expected_date:
        log.error(
            "State candidate %s has meme schedule_date=%r expected=%r for mode=%s; ignoring",
            path,
            schedule_date,
            expected_date,
            mode,
        )
        return False
    return True


def validate_meme_schedule_version_for_candidate(state: dict, *, path: Path) -> bool:
    """Validate meme schedule version for candidate."""
    version = int(state.get("meme_schedule_version", 0) or 0)
    if version > MEME_SCHEDULE_VERSION:
        log.error(
            "State candidate %s has future meme_schedule_version=%s > supported=%s; ignoring",
            path,
            version,
            MEME_SCHEDULE_VERSION,
        )
        return False
    if version < MEME_SCHEDULE_VERSION:
        log.info(
            "State candidate %s has old meme_schedule_version=%s; deferring schedule validation to migration",
            path,
            version,
        )
        return True
    return validate_meme_schedule_state(state, path=path)


class IncompatibleStateReaderError(RuntimeError):
    """Raised when durable state requires a newer executable."""


def require_compatible_state_reader(
    state: dict,
    *,
    path: Path,
    reader_version: int | None = None,
) -> int:
    """Return the declared minimum after rejecting an incompatible reader."""
    raw_minimum = state.get("minimum_reader_version", 1)
    if type(raw_minimum) is not int or raw_minimum < 1:
        raise IncompatibleStateReaderError(
            f"State candidate {path} has invalid minimum reader version "
            f"{raw_minimum!r}"
        )
    supported = STATE_READER_VERSION if reader_version is None else reader_version
    if type(supported) is not int or supported < 1:
        raise ValueError("reader_version must be a positive integer")
    if raw_minimum > supported:
        raise IncompatibleStateReaderError(
            f"State candidate {path} requires minimum reader version "
            f"{raw_minimum}, but this executable supports {supported}; refusing "
            "state mutation and backup fallback"
        )
    return raw_minimum


def state_document_for_persistence(state: dict) -> dict:
    """Return state with the reader declaration and pre-reader rollback fence."""
    minimum = require_compatible_state_reader(state, path=STATE_FILE)
    legacy_drafts = state.get("pending_reply_drafts")
    if legacy_drafts not in (None, {}, STATE_READER_COMPATIBILITY_FENCE):
        raise RuntimeError(
            "Legacy V1 reply drafts remain in runtime state; refusing to "
            "overwrite them with the reader compatibility fence"
        )
    document = dict(state)
    experiment_state = document.get("engagement_question_experiment")
    if experiment_state is not None:
        engagement_question_trial.validate_experiment_state(experiment_state)
    document["minimum_reader_version"] = max(
        minimum,
        STATE_MINIMUM_READER_VERSION,
        (
            ENGAGEMENT_QUESTION_EXPERIMENT_STATE_MINIMUM_READER_VERSION
            if experiment_state is not None
            else STATE_MINIMUM_READER_VERSION
        ),
    )
    document["pending_reply_drafts"] = copy.deepcopy(
        STATE_READER_COMPATIBILITY_FENCE
    )
    return document


def normalise_state_candidate(
    state: dict,
    *,
    path: Path,
    recovery_events: list[dict[str, object]] | None = None,
    recover_pending_identity: bool = False,
) -> dict | None:
    """Normalise state candidate."""
    minimum_reader_version = require_compatible_state_reader(state, path=path)
    list_keys = {
        "replied_to_ids",
        "dry_run_seen_mention_ids",
        "skipped_hot_reply_ids",
        "daily_replied_author_ids",
        "own_auto_reply_ids",
        "posted_meme_filenames",
        "recent_own_post_ids",
        "seen_quote_post_ids",
        "replied_to_quote_post_ids",
        "skipped_quote_post_ids",
        "quote_spam_author_ids",
    }
    epoch_list_keys = {"x_error_epochs", "x_write_error_epochs", "xai_error_epochs", "quote_x_error_epochs"}
    string_map_keys = {
        "hot_post_reply_since_ids",
        "hot_post_reply_pagination_tokens",
        "quote_lookup_pagination_tokens",
    }
    int_map_keys = {"hot_post_reply_check_counts", "daily_replied_author_counts"}
    record_map_keys = {
        "skipped_hot_reply_records",
        "pending_ai_reply_drafts",
        "reply_evaluation_records",
        "clarification_reply_records",
    }
    optional_scalar_keys = {
        "daily_reply_date",
        "daily_quote_reply_date",
        "last_regular_image_filename",
    }
    optional_numeric_id_keys = {
        "last_seen_mention_id",
        "last_main_post_id",
    }
    int_keys = {
        "daily_reply_count",
        "meme_schedule_version",
        "daily_quote_reply_count",
        "original_regular_posts_since_generated_image",
    }
    epoch_keys = {
        "last_meme_post_epoch",
        "next_meme_post_epoch",
        "meme_anchor_quote_post_epoch",
        "last_reply_epoch",
        "last_quote_post_epoch",
        "next_quote_post_epoch",
        "api_cooldown_until_epoch",
        "x_write_api_cooldown_until_epoch",
        "xai_api_cooldown_until_epoch",
        "quote_api_cooldown_until_epoch",
    }

    normalised = default_state()
    normalised.update(state)
    normalised["minimum_reader_version"] = max(
        minimum_reader_version,
        STATE_MINIMUM_READER_VERSION,
    )

    if "engagement_question_experiment" in state:
        try:
            normalised["engagement_question_experiment"] = (
                engagement_question_trial.validate_experiment_state(
                    state["engagement_question_experiment"]
                )
            )
        except engagement_question_trial.ExperimentValidationError:
            log.error(
                "State candidate %s has invalid engagement-question experiment state; ignoring",
                path,
                exc_info=True,
            )
            return None
        normalised["minimum_reader_version"] = max(
            normalised["minimum_reader_version"],
            ENGAGEMENT_QUESTION_EXPERIMENT_STATE_MINIMUM_READER_VERSION,
        )

    for key in list_keys:
        if key in state:
            value = normalise_string_list(state[key], key=key, path=path)
            if value is None:
                return None
            normalised[key] = value
    if "recent_confirmed_regular_images" in state:
        recent_images = normalise_recent_confirmed_regular_images(
            state["recent_confirmed_regular_images"], path=path
        )
        if recent_images is None:
            normalised["recent_confirmed_regular_images"] = []
            open_original_editorial_circuit_breaker("recent_history_invalid")
            log.critical(
                "Discarded corrupt editorial recent-image guard state from %s; "
                "ordinary posting remains available with editorial production disabled",
                path,
            )
        else:
            normalised["recent_confirmed_regular_images"] = recent_images
    for key in epoch_list_keys:
        if key in state:
            value = normalise_epoch_list(state[key], key=key, path=path)
            if value is None:
                return None
            normalised[key] = value
    for key in string_map_keys:
        if key in state:
            value = normalise_string_map(state[key], key=key, path=path)
            if value is None:
                return None
            normalised[key] = value
    if "quote_lookup_repeated_cursor_suppressions" in state:
        value, discarded = normalise_quote_repeated_cursor_suppressions(
            state["quote_lookup_repeated_cursor_suppressions"]
        )
        normalised["quote_lookup_repeated_cursor_suppressions"] = value
        if discarded and recovery_events is not None:
            recovery_events.append({
                "kind": "quote_cursor_suppression_pruned",
                "discarded_entries": discarded,
            })
    for key in int_map_keys:
        if key in state:
            value = normalise_int_map(state[key], key=key, path=path)
            if value is None:
                return None
            normalised[key] = value
    for key in record_map_keys:
        if key in state:
            value = normalise_record_map(state[key], key=key, path=path)
            if value is None:
                return None
            normalised[key] = value
    if "mention_pending_candidates" in state:
        pending_value = canonical_mention_pending_candidates(
            state["mention_pending_candidates"],
            path=path,
        )
        if pending_value is None and not recover_pending_identity:
            return None
        if pending_value is not None:
            normalised["mention_pending_candidates"] = pending_value
    for key in optional_scalar_keys:
        if key in state:
            value = normalise_optional_scalar(state[key], key=key, path=path)
            if value is None:
                return None
            normalised[key] = value or None
    for key in optional_numeric_id_keys:
        if key in state:
            value = normalise_optional_numeric_id(state[key], key=key, path=path)
            if value is None:
                return None
            normalised[key] = value or None
    if "tweet_cache" in state:
        value = normalise_tweet_cache(state["tweet_cache"], path=path)
        if value is None:
            return None
        normalised["tweet_cache"] = value
    if "reply_strategy_history" in state:
        history = state["reply_strategy_history"]
        if not isinstance(history, list) or any(not isinstance(item, dict) for item in history):
            log.error("State candidate %s has invalid reply_strategy_history; ignoring", path)
            return None
        normalised["reply_strategy_history"] = history[-1000:]
    if "ai_reply_history" in state:
        history = state["ai_reply_history"]
        if not isinstance(history, list) or any(not isinstance(item, dict) for item in history):
            log.error("State candidate %s has invalid ai_reply_history; ignoring", path)
            return None
        normalised["ai_reply_history"] = history[-1000:]
    if "mention_pagination" in state:
        value = normalise_mention_pagination(state["mention_pagination"], path=path)
        if value is None:
            return None
        normalised["mention_pagination"] = value
    if "mention_backlog_reset_guard" in state:
        value = normalise_mention_backlog_reset_guard(
            state["mention_backlog_reset_guard"],
            path=path,
        )
        if value is None:
            return None
        normalised["mention_backlog_reset_guard"] = value
    if "mention_backlog" in state:
        raw_backlog = state["mention_backlog"]
        token_overflow = (
            isinstance(raw_backlog, dict)
            and isinstance(raw_backlog.get("seen_tokens"), list)
            and len(raw_backlog["seen_tokens"])
            > MENTION_BACKLOG_CONTINUATION_TOKEN_LIMIT
        )
        value = normalise_mention_backlog(
            raw_backlog,
            path=path,
            reset_token_overflow=token_overflow,
        )
        if value is None:
            return None
        normalised["mention_backlog"] = value
        if token_overflow:
            normalised["mention_pagination"] = {}
            normalised["mention_pending_candidates"] = {}
            normalised["mention_backlog_reset_guard"] = {
                "base_since_id": str(
                    normalised.get("last_seen_mention_id") or ""
                ),
                "head_traversal_started": False,
            }
            if recovery_events is not None:
                recovery_events.append({
                    "reason": "continuation_token_limit",
                    "since_id": str(raw_backlog.get("since_id") or "") or None,
                    "pages_completed": raw_backlog.get("pages_completed"),
                    "token_fingerprint": hashlib.sha256(
                        str(raw_backlog.get("next_token") or "").encode("utf-8")
                    ).hexdigest()[:16],
                })
    # Retire legacy quarantine-only terminal records before they can suppress
    # a completed-page pending candidate that the watermark will not refetch.
    prune_reply_evaluation_records(normalised)
    pending_authority_usable, _pending_authority_changed = (
        validate_pending_mention_candidate_authority(
            normalised,
            path=path,
            recover_pending_identity=recover_pending_identity,
            recovery_events=recovery_events,
        )
    )
    if not pending_authority_usable:
        return None
    if "author_evaluation_quarantines" in state:
        value = normalise_author_evaluation_quarantines(
            state["author_evaluation_quarantines"],
            path=path,
        )
        if value is None:
            return None
        normalised["author_evaluation_quarantines"] = value
    for key in int_keys:
        if key not in state:
            continue
        value = normalise_state_int(state[key], key=key, path=path)
        if value is None:
            return None
        normalised[key] = value
    if "original_regular_posts_since_generated_image" not in state:
        last_regular_image = str(normalised.get("last_regular_image_filename") or "")
        if generated_image_origin_quote_hash(last_regular_image):
            normalised["original_regular_posts_since_generated_image"] = 0
        else:
            normalised["original_regular_posts_since_generated_image"] = generated_image_spacing_required()
    for key in epoch_keys:
        if key not in state:
            continue
        value = normalise_state_epoch(state[key], key=key, path=path)
        if value is None:
            return None
        normalised[key] = value

    if not validate_meme_schedule_version_for_candidate(normalised, path=path):
        return None

    prune_author_evaluation_quarantines(normalised)

    return normalised


def load_state() -> dict:
    """Load, validate, and recover runtime state from durable storage."""
    log.debug("Loading state from %s", STATE_FILE)

    candidates = [STATE_FILE]
    candidates.extend(STATE_FILE.with_name(f"{STATE_FILE.name}.bak{i}") for i in range(1, STATE_BACKUP_COUNT + 1))

    existing_candidates = False
    candidate_recoveries: dict[Path, list[dict[str, object]]] = {}

    def emit_candidate_recoveries(candidate: Path) -> None:
        for recovery in candidate_recoveries.get(candidate, []):
            if recovery.get("kind") == "quote_cursor_suppression_pruned":
                log.info(
                    "Pruned %s malformed, expired, or excess quote cursor "
                    "suppression entry or entries while loading %s",
                    recovery.get("discarded_entries"),
                    candidate,
                )
                continue
            reason = recovery.get("reason")
            if reason == "orphaned_pending_candidates":
                log.warning(
                    "Discarding %s uncovered pending mention candidate(s) "
                    "without pagination provenance while loading %s; watermark "
                    "remains unchanged and a reset guard was installed",
                    recovery.get("discarded_candidates"),
                    candidate,
                )
            elif reason == "continuation_token_limit":
                log.warning(
                    "Resetting oversized mention backlog while loading %s; "
                    "watermark remains unchanged and pending candidates were discarded",
                    candidate,
                )
            else:
                log.warning(
                    "Resetting unsafe mention candidate authority while loading %s "
                    "reason=%s; watermark remains unchanged",
                    candidate,
                    reason,
                )
            log_event("mention_backlog_reset", **recovery)

    def persist_candidate_recoveries(candidate: Path, state: dict) -> None:
        """Commit safe state repairs before any post-load provider work."""
        if not candidate_recoveries.get(candidate):
            return
        save_state(state, durable=True)

    def load_candidate(
        candidate: Path,
        *,
        reject_legacy: bool,
        recover_pending_identity: bool = False,
    ) -> dict | None:
        nonlocal existing_candidates
        try:
            present, data = read_stable_owned_json_bytes_no_follow(candidate)
        except UnsafeDurableStateNamespace:
            existing_candidates = True
            log.critical(
                "State candidate namespace is unsafe; refusing backup fallback: %s",
                candidate,
                exc_info=True,
            )
            raise
        if not present or data is None:
            log.warning("State file candidate does not exist: %s", candidate)
            return None
        existing_candidates = True

        try:
            state = json.loads(data.decode("utf-8"))
        except Exception:
            log.exception("Failed loading state candidate %s", candidate)
            return None

        if not isinstance(state, dict):
            log.error("State file candidate %s is not a JSON object; ignoring", candidate)
            return None
        minimum_reader_version = require_compatible_state_reader(
            state,
            path=candidate,
        )
        legacy_drafts = state.get("pending_reply_drafts")
        if minimum_reader_version >= STATE_MINIMUM_READER_VERSION:
            if legacy_drafts != STATE_READER_COMPATIBILITY_FENCE:
                message = (
                    f"State candidate {candidate} declares minimum reader version "
                    f"{minimum_reader_version} without the exact compatibility "
                    "fence; refusing unsafe rollback state"
                )
                if reject_legacy:
                    log.critical(message)
                    raise RuntimeError(message)
                log.warning(
                    "%s; candidate is not needed because primary state is usable",
                    message,
                )
                return None
        elif legacy_drafts not in (None, {}):
            message = (
                f"Legacy V1 reply drafts remain in {candidate}; refusing to interpret or post them "
                "through the AI-first strategy"
            )
            if reject_legacy:
                log.critical(message)
                raise RuntimeError(message)
            log.warning("%s; candidate is not needed because primary state is usable", message)
            return None
        state.pop("pending_reply_drafts", None)
        state["minimum_reader_version"] = max(
            minimum_reader_version,
            STATE_MINIMUM_READER_VERSION,
        )
        recovery_events: list[dict[str, object]] = []
        normalised = normalise_state_candidate(
            state,
            path=candidate,
            recovery_events=recovery_events,
            recover_pending_identity=recover_pending_identity,
        )
        if normalised is not None:
            candidate_recoveries[candidate] = recovery_events
        return normalised

    latest_backup_path = STATE_FILE.with_name(f"{STATE_FILE.name}.bak1")
    primary = load_candidate(STATE_FILE, reject_legacy=True)
    if primary is not None:
        latest_backup = (
            load_candidate(latest_backup_path, reject_legacy=False)
            if STATE_BACKUP_COUNT > 0
            else None
        )
        if latest_backup is not None and latest_backup != primary:
            message = (
                "Primary state and latest committed backup are both valid but "
                "diverge; refusing to guess which durable generation is newer"
            )
            log.critical(
                "%s primary=%s backup=%s",
                message,
                STATE_FILE,
                latest_backup_path,
            )
            raise RuntimeError(message)
        emit_candidate_recoveries(STATE_FILE)
        persist_candidate_recoveries(STATE_FILE, primary)
        log_json_debug("Loaded state summary", state_debug_summary(primary))
        return primary

    # Only inspect backups until the first usable generation is found.  Older
    # snapshots are recovery fallbacks, not vetoes over a newer usable state.
    for candidate in candidates[1:]:
        recovered = load_candidate(candidate, reject_legacy=True)
        if recovered is None:
            continue
        log.warning("Recovered state from backup %s", candidate)
        emit_candidate_recoveries(candidate)
        persist_candidate_recoveries(candidate, recovered)
        log_json_debug("Loaded state summary", state_debug_summary(recovered))
        return recovered

    if existing_candidates:
        # Pending identity corruption is recoverable only after every strict
        # candidate has failed, so a usable backup always remains authoritative.
        for candidate in candidates:
            recovered = load_candidate(
                candidate,
                reject_legacy=True,
                recover_pending_identity=True,
            )
            if recovered is None:
                continue
            log.warning(
                "Recovered state candidate %s by discarding corrupt pending "
                "mention identity and requiring a head refetch",
                candidate,
            )
            emit_candidate_recoveries(candidate)
            persist_candidate_recoveries(candidate, recovered)
            log_json_debug("Loaded state summary", state_debug_summary(recovered))
            return recovered
        message = "Existing state file(s) found but no usable state or backup; refusing to start with empty state"
        log.critical(message)
        raise RuntimeError(message)

    log.error("No state file or backup found; using default state")
    return default_state()


def scheduler_epoch_from_state(state: dict, key: str, *, current: int | None = None) -> tuple[int, bool]:
    """Return the scheduler epoch from state."""
    raw_value = state.get(key, 0)
    malformed = isinstance(raw_value, bool) or (
        isinstance(raw_value, float)
        and (not math.isfinite(raw_value) or not raw_value.is_integer())
    )
    try:
        value = 0 if malformed else int(raw_value or 0)
    except (TypeError, ValueError, OverflowError):
        malformed = True
        value = 0
    if malformed:
        log.warning("Ignoring malformed scheduler epoch %s=%r", key, raw_value)

    if value < 0:
        log.warning("Ignoring negative scheduler epoch %s=%r", key, raw_value)
        value = 0

    if current is not None and value > current:
        log.warning("Ignoring future scheduler epoch %s=%r current=%s", key, raw_value, current)
        value = 0

    if malformed or type(raw_value) is not int or raw_value != value:
        state[key] = value
        return value, True

    return value, False


def copy_state_backup(src: Path, dst: Path, *, durable: bool = False) -> None:
    """Copy one exact stable state generation without following links."""

    present, data = read_stable_owned_json_bytes_no_follow(src)
    if not present or data is None:
        raise UnsafeDurableStateNamespace(
            f"state backup source disappeared before copying: {src}"
        )
    dst.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{dst.name}.",
        dir=dst.parent,
    )
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            os.fchmod(handle.fileno(), 0o600)
            handle.write(data)
            if durable:
                handle.flush()
                os.fsync(handle.fileno())
        os.replace(temporary, dst)
        if durable:
            fsync_parent_dir(dst, strict=True)
    except BaseException:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass
        raise


def rotate_state_backups_before_commit(*, durable: bool = False) -> None:
    """Rotate state backups before commit."""
    if STATE_BACKUP_COUNT <= 1 or not STATE_FILE.exists():
        return

    try:
        for i in range(STATE_BACKUP_COUNT, 2, -1):
            older = STATE_FILE.with_name(f"{STATE_FILE.name}.bak{i - 1}")
            newer = STATE_FILE.with_name(f"{STATE_FILE.name}.bak{i}")
            if older.exists():
                older.replace(newer)

        bak2 = STATE_FILE.with_name(f"{STATE_FILE.name}.bak2")
        copy_state_backup(STATE_FILE, bak2, durable=durable)
        log.debug("Previous state backup written: %s", bak2)
    except Exception:
        log.exception("Failed rotating state backups; continuing with state save")


def write_latest_state_backup(*, durable: bool = False) -> None:
    """Write latest state backup."""
    if STATE_BACKUP_COUNT <= 0 or not STATE_FILE.exists():
        return
    bak1 = STATE_FILE.with_name(f"{STATE_FILE.name}.bak1")
    copy_state_backup(STATE_FILE, bak1, durable=durable)
    log.debug("Latest committed state backup written: %s", bak1)


class StateBackupWriteError(RuntimeError):
    """Raised after canonical state commits but its latest backup write fails."""
    pass


def save_state(state: dict, *, durable: bool = False) -> None:
    """Persist state atomically, logging only a value-free structural summary."""
    if test_process_production_state_write_blocked(STATE_FILE):
        raise RuntimeError(f"Refusing test-process write to production state: {STATE_FILE}")
    log.debug("Saving state to %s", STATE_FILE)
    log_json_debug("State summary being saved", state_debug_summary(state))
    persisted_state = state_document_for_persistence(state)

    STATE_FILE.parent.mkdir(parents=True, exist_ok=True)

    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{STATE_FILE.name}.",
        dir=STATE_FILE.parent,
    )
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            os.fchmod(handle.fileno(), 0o600)
            json.dump(persisted_state, handle, indent=2, sort_keys=True)
            if durable:
                handle.flush()
                os.fsync(handle.fileno())

        rotate_state_backups_before_commit(durable=durable)
        os.replace(temporary, STATE_FILE)
        if durable:
            fsync_parent_dir(STATE_FILE, strict=durable)
    except BaseException:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass
        raise
    try:
        write_latest_state_backup(durable=durable)
    except Exception as exc:
        raise StateBackupWriteError(
            f"Canonical state committed but latest backup write failed: {STATE_FILE}"
        ) from exc


def reset_daily_reply_count_if_needed(state: dict) -> None:
    """Reset daily reply count if needed."""
    today = reply_cap_date_str()

    if state.get("daily_reply_date") != today:
        log.info(
            "Resetting daily reply count. Previous date=%s new date=%s previous count=%s",
            state.get("daily_reply_date"),
            today,
            state.get("daily_reply_count"),
        )
        state["daily_reply_date"] = today
        state["daily_reply_count"] = 0
        state["daily_replied_author_ids"] = []
        state["daily_replied_author_counts"] = {}


def reset_daily_quote_reply_count_if_needed(state: dict) -> None:
    """Reset daily quote reply count if needed."""
    today = reply_cap_date_str()

    if state.get("daily_quote_reply_date") != today:
        log.info(
            "Resetting daily quote-reply count. Previous date=%s new date=%s previous count=%s",
            state.get("daily_quote_reply_date"),
            today,
            state.get("daily_quote_reply_count"),
        )
        state["daily_quote_reply_date"] = today
        state["daily_quote_reply_count"] = 0


def daily_author_reply_counts(state: dict) -> dict[str, int]:
    """Return the daily author reply counts."""
    counts = state.get("daily_replied_author_counts", {})
    if isinstance(counts, dict):
        cleaned: dict[str, int] = {}
        for author_id, count in counts.items():
            try:
                cleaned[str(author_id)] = max(0, int(count))
            except Exception:
                continue
        if not cleaned:
            legacy_authors = set(str(x) for x in state.get("daily_replied_author_ids", []))
            cleaned = {author_id: 1 for author_id in legacy_authors}
        state["daily_replied_author_counts"] = cleaned
        return cleaned

    legacy_authors = set(str(x) for x in state.get("daily_replied_author_ids", []))
    cleaned = {author_id: 1 for author_id in legacy_authors}
    state["daily_replied_author_counts"] = cleaned
    return cleaned


def daily_author_reply_count(state: dict, author_id: str) -> int:
    """Return the daily author reply count."""
    return daily_author_reply_counts(state).get(str(author_id), 0)


def mark_daily_author_replied(state: dict, author_id: str) -> None:
    """Mark daily author replied."""
    author_id = str(author_id)
    counts = daily_author_reply_counts(state)
    counts[author_id] = counts.get(author_id, 0) + 1
    state["daily_replied_author_counts"] = counts

    state["daily_replied_author_ids"] = append_unique_capped(
        state.get("daily_replied_author_ids", []),
        author_id,
        1000,
    )


CLARIFICATION_CUE_RE = re.compile(
    r"\b(?:you\s+)?(?:did(?:n't|\s+not)|does(?:n't|\s+not)|have(?:n't|\s+not))\s+answer(?:ed)?\b"
    r"|\b(?:your|that|the)\s+(?:reply|answer)\s+(?:did(?:n't|\s+not)|does(?:n't|\s+not))\s+answer\b"
    r"|\b(?:that(?:'s|\s+is|\s+was)\s+)?not\s+(?:what|the\s+question)\s+(?:i\s+)?asked\b"
    r"|\banswer\s+(?:my|the)\s+question\b"
    r"|\b(?:you\s+)?(?:avoided|evaded)\s+(?:my|the)\s+question\b",
    re.IGNORECASE,
)
CLARIFICATION_TOKEN_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9'-]{2,}")
CLARIFICATION_TOKEN_STOPWORDS = {
    "answer", "asked", "did", "does", "from", "have", "people", "question",
    "that", "the", "their", "then", "they", "this", "towards", "what", "when",
    "where", "which", "who", "with", "you", "your",
}


def clarification_thread_id(candidate: dict) -> str:
    """Return the clarification thread ID."""
    return str(candidate.get("conversation_id") or candidate.get("id") or "")


def clarification_thread_is_terminal(state: dict, candidate: dict) -> bool:
    """Return whether clarification thread is terminal."""
    records = state.get("clarification_reply_records", {})
    return isinstance(records, dict) and clarification_thread_id(candidate) in records


def author_used_clarification_recently(state: dict, author_id: str, *, current: int) -> bool:
    """Return the author used clarification recently."""
    records = state.get("clarification_reply_records", {})
    if not isinstance(records, dict):
        return False
    cutoff = int(current) - CLARIFICATION_REPLY_WINDOW_SECONDS
    for record in records.values():
        if not isinstance(record, dict) or str(record.get("author_id") or "") != str(author_id):
            continue
        try:
            if int(record.get("completed_epoch", 0) or 0) > cutoff:
                return True
        except (TypeError, ValueError):
            continue
    return False


def _clarification_tokens(text: object) -> set[str]:
    without_handles = re.sub(r"(?<![A-Za-z0-9_])@[A-Za-z0-9_]+", " ", str(text or ""))
    return {
        token.lower() for token in CLARIFICATION_TOKEN_RE.findall(without_handles)
        if token.lower() not in CLARIFICATION_TOKEN_STOPWORDS
    }


def clarification_reply_context(
    state: dict,
    candidate: dict,
    *,
    current: int,
) -> dict | None:
    """Return bounded repair metadata only for a direct follow-up to our confirmed reply."""
    if not conversational_reply_pipeline_enabled() or clarification_thread_is_terminal(state, candidate):
        return None
    author_id = str(candidate.get("author_id") or "")
    if not author_id or author_used_clarification_recently(state, author_id, current=current):
        return None

    try:
        prior_bot_reply_id = get_immediate_parent_id(candidate)
    except ApiError:
        return None
    if not prior_bot_reply_id or prior_bot_reply_id not in {
        str(item) for item in state.get("own_auto_reply_ids", [])
    }:
        return None

    cache = state.get("tweet_cache", {})
    if not isinstance(cache, dict):
        return None
    prior_bot_reply = cache.get(prior_bot_reply_id)
    if not is_our_auto_reply(prior_bot_reply, state):
        return None
    try:
        original_question_id = get_immediate_parent_id(prior_bot_reply)
    except ApiError:
        return None
    original_question = cache.get(str(original_question_id or ""))
    if not isinstance(original_question, dict):
        return None
    if str(original_question.get("author_id") or "") != author_id:
        return None

    thread_id = clarification_thread_id(candidate)
    if not thread_id or str(original_question.get("conversation_id") or original_question_id) != thread_id:
        return None
    question_text = str(original_question.get("text") or "")
    incoming_text = str(candidate.get("text") or "")
    if "?" not in question_text:
        return None

    explicit_correction = bool(CLARIFICATION_CUE_RE.search(incoming_text))
    restated_question = "?" in incoming_text
    if restated_question:
        restated_question = bool(
            _clarification_tokens(question_text) & _clarification_tokens(incoming_text)
        )
    if not explicit_correction and not restated_question:
        return None

    return {
        "thread_id": thread_id,
        "prior_bot_reply_id": prior_bot_reply_id,
        "original_question_id": str(original_question_id),
        "question_text": question_text,
        "trigger": "explicit_correction" if explicit_correction else "restated_question",
    }


# ---------------------------------------------------------------------
# Time / cooldown / error handling
# ---------------------------------------------------------------------

def now_epoch() -> int:
    """Return the now epoch."""
    if TEST_MODE and os.getenv("MRS_FAKE_NOW_EPOCH"):
        return int(os.getenv("MRS_FAKE_NOW_EPOCH", "0"))
    return int(datetime.now().timestamp())


def current_datetime() -> datetime:
    """Return the current datetime."""
    return datetime.fromtimestamp(now_epoch())


def parse_x_datetime_to_epoch(value: str | None) -> int | None:
    """Parse x datetime to epoch."""
    if not value:
        return None

    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        return int(parsed.timestamp())
    except Exception:
        log.warning("Could not parse X datetime: %r", value)
        return None


def parse_tweet_id(value: object, *, context: str) -> int | None:
    """Parse tweet ID."""
    value_str = str(value or "")
    if not re.fullmatch(r"\d{1,30}", value_str):
        log.warning("Skipping %s with invalid tweet id=%r", context, value)
        return None
    return int(value_str)


def valid_tweets_sorted_by_id(tweets: list[dict], *, context: str) -> list[dict]:
    """Return whether valid tweets sorted by ID."""
    valid: list[tuple[int, dict]] = []
    seen_ids: set[int] = set()
    for tweet in tweets:
        tweet_id = parse_tweet_id(tweet.get("id"), context=context)
        if tweet_id is None:
            continue
        if tweet_id in seen_ids:
            log.warning("Dropping duplicate %s tweet id=%s from paged API results", context, tweet_id)
            continue
        seen_ids.add(tweet_id)
        valid.append((tweet_id, tweet))
    return [tweet for _, tweet in sorted(valid, key=lambda item: item[0])]


def in_api_cooldown(state: dict, *, scope: str = "api") -> bool:
    """Return the in API cooldown."""
    if scope == "quote":
        until = int(state.get("quote_api_cooldown_until_epoch", 0) or 0)
        reason = state.get("quote_api_cooldown_reason", "Quote API cooldown")
        label = "Quote API cooldown"
    elif scope == "xai":
        until = int(state.get("xai_api_cooldown_until_epoch", 0) or 0)
        reason = state.get("xai_api_cooldown_reason", "xAI API cooldown")
        label = "xAI API cooldown"
    elif scope == "write":
        until = int(state.get("x_write_api_cooldown_until_epoch", 0) or 0)
        reason = state.get("x_write_api_cooldown_reason", "X write API cooldown")
        label = "X write API cooldown"
    else:
        until = int(state.get("api_cooldown_until_epoch", 0) or 0)
        reason = state.get("api_cooldown_reason", "X read API cooldown")
        label = "X read API cooldown"

    if until <= now_epoch():
        return False

    until_human = datetime.fromtimestamp(until).strftime("%Y-%m-%d %H:%M:%S")
    log.warning("%s active until %s: %s", label, until_human, reason)
    return True


def clear_expired_api_cooldowns(state: dict) -> bool:
    """Clear expired API cooldowns."""
    changed = False
    current = now_epoch()

    for until_key, reason_key, label in (
        ("api_cooldown_until_epoch", "api_cooldown_reason", "X read API cooldown"),
        ("x_write_api_cooldown_until_epoch", "x_write_api_cooldown_reason", "X write API cooldown"),
        ("xai_api_cooldown_until_epoch", "xai_api_cooldown_reason", "xAI API cooldown"),
        ("quote_api_cooldown_until_epoch", "quote_api_cooldown_reason", "Quote API cooldown"),
    ):
        until = int(state.get(until_key, 0) or 0)
        if until <= 0 or until > current:
            continue

        log.info(
            "Clearing expired %s. until_epoch=%s reason=%s",
            label,
            until,
            state.get(reason_key, ""),
        )
        state[until_key] = 0
        state[reason_key] = ""
        changed = True

    return changed


def sanitize_next_reply_lane_priority(state: dict) -> bool:
    """Sanitise next reply lane priority."""
    priority = str(state.get("next_reply_lane_priority", "normal") or "normal")
    if priority in {"normal", "quote"}:
        if state.get("next_reply_lane_priority") != priority:
            state["next_reply_lane_priority"] = priority
            return True
        return False

    log.warning("Invalid next_reply_lane_priority=%r; using normal", state.get("next_reply_lane_priority"))
    state["next_reply_lane_priority"] = "normal"
    return True


def load_runtime_state() -> dict:
    """Load runtime state and apply daily maintenance safely."""
    state = load_state()
    clear_expired_api_cooldowns(state)
    sanitize_next_reply_lane_priority(state)
    return state


def prune_error_epochs(epochs: list[int]) -> list[int]:
    """Prune error epochs."""
    cutoff = now_epoch() - ERROR_WINDOW_SECONDS
    pruned = [int(e) for e in epochs if int(e) >= cutoff]
    log.debug("Pruned error epochs from %d to %d", len(epochs), len(pruned))
    return pruned


def cooldown_until_for_rate_limit(current: int, reset_epoch: int | None) -> int:
    """Return the cooldown until for rate limit."""
    if reset_epoch and reset_epoch > current:
        return reset_epoch + 60
    return current + COOLDOWN_AFTER_429_SECONDS


def record_api_error(state: dict, error: Exception, service: str, *, scope: str = "api") -> None:
    """Record API error."""
    if service == "x" and scope == "write" and api_error_is_reply_not_allowed(error):
        log.warning(
            "Not recording terminal target-specific X reply restriction in the transient write-error window: %s",
            error,
        )
        return

    current = now_epoch()

    if service == "x" and scope == "quote":
        key = "quote_x_error_epochs"
        max_errors = MAX_X_ERRORS_PER_WINDOW
        cooldown_until_key = "quote_api_cooldown_until_epoch"
        cooldown_reason_key = "quote_api_cooldown_reason"
    elif service == "x" and scope == "write":
        key = "x_write_error_epochs"
        max_errors = MAX_X_ERRORS_PER_WINDOW
        cooldown_until_key = "x_write_api_cooldown_until_epoch"
        cooldown_reason_key = "x_write_api_cooldown_reason"
    elif service == "x":
        key = "x_error_epochs"
        max_errors = MAX_X_ERRORS_PER_WINDOW
        cooldown_until_key = "api_cooldown_until_epoch"
        cooldown_reason_key = "api_cooldown_reason"
    else:
        key = "xai_error_epochs"
        max_errors = MAX_XAI_ERRORS_PER_WINDOW
        cooldown_until_key = "xai_api_cooldown_until_epoch"
        cooldown_reason_key = "xai_api_cooldown_reason"

    epochs = prune_error_epochs(state.get(key, []))
    epochs.append(current)
    state[key] = epochs

    status_code = getattr(error, "status_code", None)
    reset_epoch = getattr(error, "reset_epoch", None)
    diagnostic_event = getattr(error, "diagnostic_event", None)
    diagnostic_sha256 = getattr(error, "diagnostic_sha256", None)

    if diagnostic_event is not None or diagnostic_sha256 is not None:
        log.warning(
            "Recorded %s API error. status_code=%s errors_in_window=%d/%d "
            "reset_epoch=%s diagnostic_event=%s diagnostic_sha256=%s error=%s",
            f"{scope}/{service}" if scope != "api" else service,
            status_code,
            len(epochs),
            max_errors,
            reset_epoch,
            diagnostic_event,
            diagnostic_sha256,
            error,
        )
    else:
        log.warning(
            "Recorded %s API error. status_code=%s errors_in_window=%d/%d "
            "reset_epoch=%s error=%s",
            f"{scope}/{service}" if scope != "api" else service,
            status_code,
            len(epochs),
            max_errors,
            reset_epoch,
            error,
        )

    if status_code == 429:
        state[cooldown_until_key] = cooldown_until_for_rate_limit(current, reset_epoch)
        state[cooldown_reason_key] = f"{scope}/{service} returned 429/rate limit" if scope != "api" else f"{service} returned 429/rate limit"
        log.error(
            "Entering API cooldown after 429 until %s",
            datetime.fromtimestamp(state[cooldown_until_key]).strftime("%Y-%m-%d %H:%M:%S"),
        )
        save_state(state)
        return

    if len(epochs) >= max_errors:
        state[cooldown_until_key] = current + COOLDOWN_AFTER_REPEATED_ERRORS_SECONDS
        state[cooldown_reason_key] = (
            f"too many {scope}/{service} API errors in the last hour"
            if scope != "api"
            else f"too many {service} API errors in the last hour"
        )
        log.error(
            "Entering API cooldown after repeated errors until %s",
            datetime.fromtimestamp(state[cooldown_until_key]).strftime("%Y-%m-%d %H:%M:%S"),
        )
        save_state(state)


# ---------------------------------------------------------------------
# X API helpers
# ---------------------------------------------------------------------

def x_request_base_url(method: str, path: str) -> str:
    """Select the configured origin for one literal X request.

    Only the exact authorised v2 media-upload write uses the optional upload
    origin.  Reads, tweet creation and every non-literal spelling stay on the
    primary X API origin.
    """

    if str(method) == "POST" and str(path) == "/2/media/upload":
        return X_UPLOAD_BASE
    return X_BASE


def normalised_prepared_x_request_path(method: str, path: str) -> str:
    """Return the conservative path which Requests will place on the wire.

    ``requests`` normalises dot segments and some percent-encoded characters
    while preparing a request.  Security decisions made against the caller's
    unprepared string can therefore misclassify a tweet-create target.  Decode
    repeatedly as a conservative allowance for an upstream HTTP router doing
    another decoding pass, normalise separators/dot segments, and collapse
    repeated slashes before comparing protected endpoints.
    """

    try:
        prepared = requests.Request(
            method=str(method).upper(),
            url=f"{x_request_base_url(method, path)}{path}",
        ).prepare()
    except requests.RequestException as exc:
        raise AmbiguousRemotePostOutcome(
            "X request target could not be prepared safely",
            service="x",
            request_method=method,
            request_path=path,
        ) from exc
    prepared_url = prepared.url
    if not isinstance(prepared_url, str) or not prepared_url:
        raise AmbiguousRemotePostOutcome(
            "X request target preparation returned no usable URL",
            service="x",
            request_method=method,
            request_path=path,
        )
    normalised = urlsplit(prepared_url).path
    for _pass in range(4):
        decoded = unquote(normalised)
        if decoded == normalised:
            break
        normalised = decoded
    normalised = normalised.replace("\\", "/")
    normalised = posixpath.normpath(normalised)
    normalised = re.sub(r"/+", "/", normalised)
    if not normalised.startswith("/"):
        normalised = f"/{normalised}"
    return normalised


def x_request_targets_tweet_create(method: str, path: str) -> bool:
    """Return whether one prepared X request targets the tweet-create route."""

    return prepared_x_create_route(method, path) == "tweet"


def x_request_targets_media_upload(method: str, path: str) -> bool:
    """Return whether one prepared X request targets the v2 media-create route."""

    return prepared_x_create_route(method, path) == "media"


def prepared_x_create_route(method: str, path: str) -> str | None:
    """Classify the create route produced by Requests preparation."""

    if str(method).upper() != "POST":
        return None
    prepared_path = normalised_prepared_x_request_path(method, path).rstrip("/")
    if prepared_path == "/2/tweets":
        return "tweet"
    if prepared_path == "/2/media/upload":
        return "media"
    return None


def exact_x_create_route(method: str, path: str) -> str | None:
    """Return the exact authorised create route, without URL normalisation.

    URL decoding and path normalisation are useful for recognising a route that
    must be rejected, but they are not authority: an authorised create must use
    one literal method/path pair with no query, fragment, alternate spelling or
    legacy endpoint.
    """

    if str(method) != "POST":
        return None
    if str(path) == "/2/tweets":
        return "tweet"
    if str(path) == "/2/media/upload":
        return "media"
    return None


def frozen_strict_json_object(value: object, *, label: str) -> dict:
    """Return an isolated strict-JSON copy suitable for request transport."""

    if not isinstance(value, dict):
        raise AmbiguousRemotePostOutcome(
            f"{label} must be one JSON object",
            service="x",
        )
    try:
        encoded = json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        )
        decoded = json.loads(encoded)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise AmbiguousRemotePostOutcome(
            f"{label} is not strict JSON",
            service="x",
        ) from exc
    if not isinstance(decoded, dict):
        raise AmbiguousRemotePostOutcome(
            f"{label} must remain one JSON object",
            service="x",
        )
    return decoded


if _X_REQUEST_PROVIDER_RELOAD_RECORD_STATE == "unconfigured":
    current_record_state, _current_record_fingerprint = (
        _configured_x_request_reload_record(sys.modules[__name__])
    )
    if current_record_state != "unconfigured":
        raise RuntimeError(
            "Configured X request authority changed during module import"
        )
    _install_configured_x_request_provider(
        lambda _url=f"{x_request_base_url('POST', '/2/tweets')}/2/tweets",
        _auth=AUTH,
        _timeout=request_timeout(): (_url, _auth, _timeout),
        owner_module=sys.modules[__name__],
        reload_fingerprint=_CURRENT_X_REQUEST_PROVIDER_RELOAD_FINGERPRINT,
    )
else:
    current_record_state, current_record_fingerprint = (
        _configured_x_request_reload_record(sys.modules[__name__])
    )
    if (
        current_record_state != "installed"
        or current_record_fingerprint
        != _CURRENT_X_REQUEST_PROVIDER_RELOAD_FINGERPRINT
    ):
        raise RuntimeError(
            "Configured X request authority changed during module reload"
        )

def print_rate_limit_headers(response: requests.Response) -> int | None:
    """Log rate limit headers."""
    log.warning("Rate Limit: %s", response.headers.get("x-rate-limit-limit"))
    log.warning("Remaining: %s", response.headers.get("x-rate-limit-remaining"))

    reset_time = response.headers.get("x-rate-limit-reset")
    if not reset_time:
        return None

    try:
        reset_epoch = int(reset_time)
    except (TypeError, ValueError):
        log.warning("Rate Limit Resets At: %s", reset_time)
        return None

    try:
        reset_time_human = datetime.fromtimestamp(reset_epoch).strftime("%Y-%m-%d %H:%M:%S")
        log.warning("Rate Limit Resets At: %s", reset_time_human)
        return reset_epoch
    except Exception:
        log.warning("Rate Limit Resets At invalid epoch: %s", reset_time)
        return None


X_CREATE_RESPONSE_ANOMALY_EVENT = "X_CREATE_RESPONSE_ANOMALY_V1"
X_CREATE_RESPONSE_ANOMALY_SCHEMA_VERSION = 1
X_CREATE_RESPONSE_ANOMALY_BODY_MAX_BYTES = 16 * 1024
X_CREATE_RESPONSE_SAFE_CORRELATION_HEADERS = (
    "request-id",
    "traceparent",
    "x-correlation-id",
    "x-request-id",
    "x-transaction-id",
)
_X_CREATE_RESPONSE_HEADER_MAX_CHARACTERS = 512
_X_CREATE_RESPONSE_ID_VALUE_MAX_CHARACTERS = 256
_X_CREATE_RESPONSE_TOP_LEVEL_KEY_LIMIT = 64
_X_CREATE_RESPONSE_TOP_LEVEL_KEY_MAX_CHARACTERS = 256


def x_create_response_anomaly_reason(decoded: object) -> str | None:
    """Return why one decoded tweet-create response cannot confirm success."""

    if not isinstance(decoded, dict):
        return "decoded_top_level_not_object"
    if "data" not in decoded:
        return "data_absent"
    data = decoded["data"]
    if not isinstance(data, dict):
        return "data_not_object"
    if "id" not in data:
        return "data_id_absent"
    post_id = data["id"]
    if type(post_id) is str and not post_id.strip():
        return "data_id_blank"
    if not valid_post_id(post_id):
        return "data_id_non_numeric"
    return None


def _x_create_diagnostic_json_type(value: object) -> str:
    """Return a stable JSON-oriented type name for decoded evidence."""

    if value is None:
        return "null"
    if type(value) is bool:
        return "boolean"
    if type(value) in {int, float}:
        return "number"
    if type(value) is str:
        return "string"
    if type(value) is list:
        return "array"
    if type(value) is dict:
        return "object"
    return f"python:{type(value).__module__}.{type(value).__qualname__}"


def _bounded_x_create_diagnostic_text(
    value: object,
    *,
    maximum_characters: int,
) -> str | None:
    """Return one bounded control-free diagnostic string, or no value."""

    if value is None:
        return None
    text = str(value)
    if (
        len(text) > maximum_characters
        or any(ord(character) < 0x20 or ord(character) == 0x7F for character in text)
    ):
        return None
    return text


def _x_create_response_elapsed_ms(response: requests.Response) -> int | None:
    """Return a finite non-negative Requests elapsed duration in milliseconds."""

    try:
        seconds = float(response.elapsed.total_seconds())
    except (AttributeError, TypeError, ValueError, OverflowError):
        return None
    if not math.isfinite(seconds) or seconds < 0:
        return None
    return int(round(seconds * 1000))


def emit_x_create_response_anomaly(
    *,
    response: requests.Response,
    transport_authority: TransportAuthority,
    request_payload: dict,
    reason: str,
    raw_body: bytes,
    json_decode_succeeded: bool,
    decoded: object,
    json_error: json.JSONDecodeError | None = None,
) -> dict[str, object]:
    """Emit one canonical, bounded ERROR event for an anomalous tweet create.

    ``diagnostic_sha256`` hashes the canonical UTF-8 JSON object before that
    hash field is added.  The complete cached response body is included only
    when it is no larger than ``X_CREATE_RESPONSE_ANOMALY_BODY_MAX_BYTES``.
    """

    raw_body = bytes(raw_body)
    raw_body_complete = (
        len(raw_body) <= X_CREATE_RESPONSE_ANOMALY_BODY_MAX_BYTES
    )
    safe_correlation_headers: dict[str, str] = {}
    for header_name in X_CREATE_RESPONSE_SAFE_CORRELATION_HEADERS:
        header_value = _bounded_x_create_diagnostic_text(
            response.headers.get(header_name),
            maximum_characters=_X_CREATE_RESPONSE_HEADER_MAX_CHARACTERS,
        )
        if header_value is not None:
            safe_correlation_headers[header_name] = header_value

    target_id: str | None = None
    reply = request_payload.get("reply")
    if isinstance(reply, dict) and type(reply.get("in_reply_to_tweet_id")) is str:
        target_id = reply["in_reply_to_tweet_id"]

    decoded_top_level_type = (
        _x_create_diagnostic_json_type(decoded)
        if json_decode_succeeded
        else None
    )
    decoded_top_level_keys: list[str] | None = None
    decoded_top_level_keys_complete: bool | None = None
    if json_decode_succeeded and isinstance(decoded, dict):
        keys = list(decoded.keys())
        if (
            len(keys) <= _X_CREATE_RESPONSE_TOP_LEVEL_KEY_LIMIT
            and all(
                type(key) is str
                and len(key) <= _X_CREATE_RESPONSE_TOP_LEVEL_KEY_MAX_CHARACTERS
                for key in keys
            )
        ):
            decoded_top_level_keys = sorted(keys)
            decoded_top_level_keys_complete = True
        else:
            decoded_top_level_keys_complete = False

    data_present = (
        json_decode_succeeded
        and isinstance(decoded, dict)
        and "data" in decoded
    )
    data_value = decoded["data"] if data_present else None
    data_type = (
        _x_create_diagnostic_json_type(data_value) if data_present else None
    )
    data_is_object = isinstance(data_value, dict) if data_present else False
    data_id_present = data_is_object and "id" in data_value
    data_id_value = data_value["id"] if data_id_present else None
    data_text_present = data_is_object and "text" in data_value
    data_text_value = data_value["text"] if data_text_present else None
    edit_history_present = data_is_object and "edit_history_tweet_ids" in data_value
    edit_history_value = (
        data_value["edit_history_tweet_ids"] if edit_history_present else None
    )

    diagnostic_data_id_value: object = None
    data_id_value_complete: bool | None = None
    if data_id_present:
        if type(data_id_value) is str:
            if len(data_id_value) <= _X_CREATE_RESPONSE_ID_VALUE_MAX_CHARACTERS:
                diagnostic_data_id_value = data_id_value
                data_id_value_complete = True
            else:
                data_id_value_complete = False
        elif data_id_value is None or type(data_id_value) in {bool, int}:
            diagnostic_data_id_value = data_id_value
            data_id_value_complete = True
        elif type(data_id_value) is float and math.isfinite(data_id_value):
            diagnostic_data_id_value = data_id_value
            data_id_value_complete = True
        else:
            data_id_value_complete = False

    event_without_hash: dict[str, object] = {
        "canonical_payload_sha256": transport_authority.payload_sha256,
        "content_length_header": _bounded_x_create_diagnostic_text(
            response.headers.get("Content-Length"),
            maximum_characters=_X_CREATE_RESPONSE_HEADER_MAX_CHARACTERS,
        ),
        "content_type": _bounded_x_create_diagnostic_text(
            response.headers.get("Content-Type"),
            maximum_characters=_X_CREATE_RESPONSE_HEADER_MAX_CHARACTERS,
        ),
        "data_id_character_length": (
            len(data_id_value) if type(data_id_value) is str else None
        ),
        "data_id_type": (
            _x_create_diagnostic_json_type(data_id_value)
            if data_id_present
            else None
        ),
        "data_id_value": diagnostic_data_id_value,
        "data_id_value_complete": data_id_value_complete,
        "data_text_character_length": (
            len(data_text_value) if type(data_text_value) is str else None
        ),
        "data_text_type": (
            _x_create_diagnostic_json_type(data_text_value)
            if data_text_present
            else None
        ),
        "data_type": data_type,
        "decoded_top_level_keys": decoded_top_level_keys,
        "decoded_top_level_keys_complete": decoded_top_level_keys_complete,
        "decoded_top_level_type": decoded_top_level_type,
        "edit_history_tweet_ids_count": (
            len(edit_history_value) if type(edit_history_value) is list else None
        ),
        "edit_history_tweet_ids_type": (
            _x_create_diagnostic_json_type(edit_history_value)
            if edit_history_present
            else None
        ),
        "event": X_CREATE_RESPONSE_ANOMALY_EVENT,
        "http_status": int(response.status_code),
        "json_decode_succeeded": json_decode_succeeded,
        "json_error_position": (
            json_error.pos
            if json_error is not None and type(getattr(json_error, "pos", None)) is int
            else None
        ),
        "json_error_type": type(json_error).__name__ if json_error is not None else None,
        "raw_body_base64": (
            base64.b64encode(raw_body).decode("ascii")
            if raw_body_complete
            else None
        ),
        "raw_body_complete": raw_body_complete,
        "raw_body_encoding": "base64" if raw_body_complete else None,
        "raw_body_length": len(raw_body),
        "raw_body_sha256": hashlib.sha256(raw_body).hexdigest(),
        "reason": reason,
        "recorded_at": now_epoch(),
        "request_method": "POST",
        "request_path": "/2/tweets",
        "response_elapsed_ms": _x_create_response_elapsed_ms(response),
        "response_encoding": _bounded_x_create_diagnostic_text(
            response.encoding,
            maximum_characters=_X_CREATE_RESPONSE_HEADER_MAX_CHARACTERS,
        ),
        "safe_correlation_headers": safe_correlation_headers,
        "schema_version": X_CREATE_RESPONSE_ANOMALY_SCHEMA_VERSION,
        "target_id": target_id,
        "transaction_id": transport_authority.transaction_id,
        "transport_lane": transport_authority.lane,
    }
    canonical_without_hash = json.dumps(
        event_without_hash,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    diagnostic_sha256 = hashlib.sha256(canonical_without_hash).hexdigest()
    event = {**event_without_hash, "diagnostic_sha256": diagnostic_sha256}
    canonical_event = json.dumps(
        event,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    log.error("%s %s", X_CREATE_RESPONSE_ANOMALY_EVENT, canonical_event)
    return event


def x_request(
    method: str,
    path: str,
    *,
    ambiguous_write: bool = False,
    _remote_write_authorization: TransportAuthority | MediaUploadAuthority | None = None,
    _remote_media_payload: ReceiptBoundMediaPayload | None = None,
    _remote_media_payload_metadata: dict[str, object] | None = None,
    **kwargs,
) -> dict:
    """Send an authenticated X API request with bounded retries."""
    url = f"{x_request_base_url(method, path)}{path}"
    prepared_create_route = prepared_x_create_route(method, path)
    exact_create_route = exact_x_create_route(method, path)
    if prepared_create_route != exact_create_route:
        raise AmbiguousRemotePostOutcome(
            "Prepared and literal X create-route classifications disagree",
            service="x",
            request_method=method,
            request_path=path,
        )
    is_post_create = prepared_create_route == "tweet"
    is_media_upload = prepared_create_route == "media"
    method_upper = str(method).upper()
    if (is_post_create or is_media_upload) and exact_create_route is None:
        raise AmbiguousRemotePostOutcome(
            "An X create route must use its exact literal method and path",
            service="x",
            request_method=method,
            request_path=path,
        )
    if method_upper not in {"GET", "HEAD", "OPTIONS"} and exact_create_route is None:
        raise AmbiguousRemotePostOutcome(
            "Generic or legacy X write routes have no durable transaction policy",
            service="x",
            request_method=method,
            request_path=path,
        )
    if ambiguous_write and exact_create_route is None:
        raise AmbiguousRemotePostOutcome(
            "Ambiguous-write handling is reserved for exact authorised create routes",
            service="x",
            request_method=method,
            request_path=path,
        )
    if isinstance(_remote_write_authorization, TransportAuthority) and not is_post_create:
        raise AmbiguousRemotePostOutcome(
            "A tweet-create transport authority cannot authorise another X endpoint",
            service="x",
            request_method=method,
            request_path=path,
        )
    if _remote_media_payload is not None and not is_media_upload:
        raise AmbiguousRemotePostOutcome(
            "A receipt-bound media body cannot authorise another X endpoint",
            service="x",
            request_method=method,
            request_path=path,
        )
    if _remote_media_payload_metadata is not None and not is_media_upload:
        raise AmbiguousRemotePostOutcome(
            "Media receipt metadata cannot authorise another X endpoint",
            service="x",
            request_method=method,
            request_path=path,
        )
    if isinstance(_remote_write_authorization, MediaUploadAuthority) and not is_media_upload:
        raise AmbiguousRemotePostOutcome(
            "A media-upload authority cannot authorise another X endpoint",
            service="x",
            request_method=method,
            request_path=path,
        )
    if _remote_write_authorization is not None and not isinstance(
        _remote_write_authorization,
        (TransportAuthority, MediaUploadAuthority),
    ):
        raise AmbiguousRemotePostOutcome(
            "X write authority has an unsupported type",
            service="x",
            request_method=method,
            request_path=path,
        )
    if is_post_create and (
        not isinstance(_remote_write_authorization, TransportAuthority)
        or not ambiguous_write
    ):
        raise AmbiguousRemotePostOutcome(
            "X post creation requires an exact durable transport-journal "
            "authorization and ambiguous-write handling",
            service="x",
            request_method=method,
            request_path=path,
        )

    expected_receipt_path: Path | None = None
    if is_post_create:
        if set(kwargs) != {"json"}:
            raise AmbiguousRemotePostOutcome(
                "X post creation accepts only one exact JSON body and no alternate "
                "body, query, header, file or redirect channel",
                service="x",
                request_method=method,
                request_path=path,
            )
        kwargs["json"] = frozen_strict_json_object(
            kwargs["json"],
            label="X post creation payload",
        )

    if is_media_upload and set(kwargs) != {"data", "files"}:
        raise AmbiguousRemotePostOutcome(
            "X media creation accepts only its exact form and media part",
            service="x",
            request_method=method,
            request_path=path,
        )

    log.debug("X request: %s %s", method, url)

    if "params" in kwargs:
        log_json_debug("X request params", kwargs["params"])

    if "json" in kwargs:
        log_json_debug("X request json", kwargs["json"])

    if "data" in kwargs:
        log_json_debug("X request form data", kwargs["data"])

    if "files" in kwargs:
        log.debug("X request includes files: %s", list(kwargs["files"].keys()))

    if method_upper not in {"GET", "HEAD", "OPTIONS"}:
        require_remote_operation_unpaused(
            f"X {method.upper()} {path}",
            transaction_authorization=_remote_write_authorization,
        )

    if ambiguous_write:
        # A redirect can turn one create into an untracked follow-up request.
        # Writes are therefore single-hop unless a future provider contract
        # explicitly proves a redirect safe.
        kwargs["allow_redirects"] = False

    if is_post_create:
        payload = kwargs.get("json")
        if not isinstance(payload, dict):
            raise AmbiguousRemotePostOutcome(
                "X post creation requires one exact JSON payload",
                service="x",
                request_method=method,
                request_path=path,
            )
        try:
            expected_receipt_path = canonical_transport_receipt_path_for_lane(
                _remote_write_authorization.lane
            )
            if expected_receipt_path is None:
                raise TransportJournalError(
                    "transport authority lane is not a canonical public-create lane"
                )
            block_if_unrelated_receipt_appeared_for_tweet_transport(
                expected_receipt_path
            )
        except TransportJournalError as exc:
            raise AmbiguousRemotePostOutcome(
                "X post creation lost its exact durable transport authority",
                service="x",
                request_method=method,
                request_path=path,
            ) from exc

    if is_media_upload and (
        not isinstance(_remote_write_authorization, MediaUploadAuthority)
        or not ambiguous_write
    ):
        raise AmbiguousRemotePostOutcome(
            "X media upload requires exact durable media authority and explicit "
            "ambiguous-write handling",
            service="x",
            request_method=method,
            request_path=path,
        )
    if is_media_upload:
        files = kwargs.get("files")
        form = kwargs.get("data")
        media_part = files.get("media") if isinstance(files, dict) else None
        if (
            not isinstance(media_part, tuple)
            or len(media_part) != 3
            or not isinstance(media_part[0], str)
            or type(media_part[1]) is not bytes
            or not isinstance(media_part[2], str)
            or not isinstance(form, dict)
            or not isinstance(_remote_media_payload, ReceiptBoundMediaPayload)
            or media_part
            != (
                _remote_media_payload.basename,
                _remote_media_payload.data,
                _remote_media_payload.mime_type,
            )
        ):
            raise AmbiguousRemotePostOutcome(
                "X media upload request is not an exact bound multipart payload",
                service="x",
                request_method=method,
                request_path=path,
            )
        try:
            receipt_payload_metadata = (
                media_upload_payload_metadata(form)
                if _remote_media_payload_metadata is None
                else validate_media_upload_payload_metadata(
                    _remote_media_payload_metadata,
                    form=form,
                )
            )
        except (TypeError, ValueError) as exc:
            raise AmbiguousRemotePostOutcome(
                "X media upload receipt metadata does not match its exact form",
                service="x",
                request_method=method,
                request_path=path,
            ) from exc
        try:
            editorial_selection = receipt_payload_metadata.get(
                "original_editorial_selection"
            )
            if editorial_selection is None:
                block_if_unrelated_receipt_appeared_for_media_transport()
            else:
                block_if_unrelated_receipt_appeared_for_media_transport(
                    original_editorial_selection=editorial_selection
                )
            consume_media_upload_authority(
                MEDIA_UPLOAD_RECEIPT_FILE,
                _remote_write_authorization,
                payload=_remote_media_payload,
                lane=_remote_write_authorization.lane,
                mime_type=media_part[2],
                payload_metadata=receipt_payload_metadata,
            )
        except MediaUploadReceiptError as exc:
            raise AmbiguousRemotePostOutcome(
                "X media upload lost its exact durable transport authority",
                service="x",
                request_method=method,
                request_path=path,
            ) from exc

    validated_error_response: ValidatedXErrorResponse | None = None
    rejection_proof: DeterministicReplyCreateRejectionProof | None = None
    read_only_request = method_upper in {"GET", "HEAD", "OPTIONS"}
    if read_only_request:
        report_bot_health_progress("x_read")
    try:
        if is_post_create:
            if expected_receipt_path is None:
                raise TransportJournalError(
                    "tweet transport has no canonical source receipt"
                )
            (
                response,
                coordinated_validated_error,
                coordinated_rejection_proof,
            ) = perform_consumed_x_request(
                Path(_remote_write_authorization.journal_path),
                _remote_write_authorization,
                request_authority=(
                    _bind_transport_authority_to_configured_x_request(
                        _remote_write_authorization,
                        payload=kwargs["json"],
                    )
                ),
                payload=kwargs["json"],
                expected_receipt_path=expected_receipt_path,
                request_kwargs=kwargs,
            )
            if isinstance(
                coordinated_validated_error,
                ValidatedXErrorResponse,
            ):
                validated_error_response = coordinated_validated_error
            if isinstance(
                coordinated_rejection_proof,
                DeterministicReplyCreateRejectionProof,
            ):
                rejection_proof = coordinated_rejection_proof
        else:
            response = requests.request(
                method,
                url,
                auth=AUTH,
                timeout=request_timeout(),
                **kwargs,
            )
    except TransportJournalError as e:
        log.exception("X request lost its exact transport authority")
        raise AmbiguousRemotePostOutcome(
            "X post creation lost its exact durable transport authority",
            service="x",
            status_code=getattr(e, "status_code", None),
            request_method=method,
            request_path=path,
        ) from e
    except requests.RequestException as e:
        log.exception("X request failed before receiving response")
        if ambiguous_write:
            raise AmbiguousRemotePostOutcome(
                str(e),
                service="x",
                request_method=method,
                request_path=path,
            ) from e
        raise ApiError(
            str(e),
            service="x",
            request_method=method,
            request_path=path,
        ) from e
    if read_only_request:
        report_bot_health_progress("x_read")

    def process_received_response() -> dict:
        nonlocal rejection_proof, validated_error_response

        log.debug("X response status: %s", response.status_code)
        log.debug(
            "X response headers: x-rate-limit-limit=%s remaining=%s reset=%s",
            response.headers.get("x-rate-limit-limit"),
            response.headers.get("x-rate-limit-remaining"),
            response.headers.get("x-rate-limit-reset"),
        )

        if not 200 <= response.status_code < 300:
            log.error("X API error %s: %s", response.status_code, response.text)
            reset_epoch = print_rate_limit_headers(response)
            if validated_error_response is None:
                try:
                    validated_error_response = parse_validated_x_error_response(
                        getattr(response, "content", None),
                        status_code=response.status_code,
                    )
                except XErrorResponseValidationError:
                    log.warning(
                        "X API non-success body was not one strict validated "
                        "error object; it cannot prove remote non-success",
                        exc_info=True,
                    )

            api_error = ApiError(
                f"X API error {response.status_code}: {response.text}",
                service="x",
                status_code=response.status_code,
                reset_epoch=reset_epoch,
                request_method=method,
                request_path=path,
                x_error_response=validated_error_response,
                x_error_message_fallback=not ambiguous_write,
            )

            if ambiguous_write:
                if rejection_proof is not None:
                    if not _activate_coordinator_reply_create_rejection_proof(
                        rejection_proof,
                        authority=_remote_write_authorization,
                    ):
                        invalidate_reply_create_rejection_proof(rejection_proof)
                        rejection_proof = None
                    else:
                        raise ProvedRemotePostNonSuccess(
                            str(api_error),
                            service="x",
                            status_code=response.status_code,
                            reset_epoch=reset_epoch,
                            request_method=method,
                            request_path=path,
                            x_error_response=validated_error_response,
                            x_error_message_fallback=False,
                            remote_non_success_proof=rejection_proof,
                        )
                raise AmbiguousRemotePostOutcome(
                    "X write outcome is not proved by HTTP status alone; "
                    f"received HTTP {response.status_code}: {response.text}",
                    service="x",
                    status_code=response.status_code,
                    reset_epoch=reset_epoch,
                    request_method=method,
                    request_path=path,
                    x_error_message_fallback=False,
                )

            raise api_error

        raw_create_body: bytes | None = None
        if is_post_create:
            # Requests has already populated its cached, decompressed content
            # for the non-streaming request.  This bytes() call cannot trigger
            # another network read.
            raw_create_body = bytes(response.content)

        def raise_create_response_anomaly(
            reason: str,
            *,
            json_decode_succeeded: bool,
            decoded: object,
            json_error: json.JSONDecodeError | None = None,
        ) -> None:
            if (
                raw_create_body is None
                or not isinstance(_remote_write_authorization, TransportAuthority)
            ):
                raise RuntimeError(
                    "tweet-create anomaly evidence requires its exact response "
                    "and transport authority"
                )
            diagnostic = emit_x_create_response_anomaly(
                response=response,
                transport_authority=_remote_write_authorization,
                request_payload=kwargs["json"],
                reason=reason,
                raw_body=raw_create_body,
                json_decode_succeeded=json_decode_succeeded,
                decoded=decoded,
                json_error=json_error,
            )
            if reason == "json_decode_error":
                outcome_summary = (
                    "X may have accepted the post but returned a non-JSON "
                    "successful response"
                )
            elif reason == "decoded_top_level_not_object":
                outcome_summary = (
                    "X may have accepted the post but its successful response "
                    f"was not a JSON object: {type(decoded).__name__}"
                )
            else:
                outcome_summary = (
                    "X may have accepted the post but its successful response "
                    "could not confirm a valid numeric data.id"
                )
            error = AmbiguousRemotePostOutcome(
                f"{outcome_summary}; "
                f"reason={reason} "
                f"diagnostic_event={X_CREATE_RESPONSE_ANOMALY_EVENT} "
                f"diagnostic_sha256={diagnostic['diagnostic_sha256']}",
                service="x",
                status_code=response.status_code,
                request_method=method,
                request_path=path,
                response_body_length=diagnostic["raw_body_length"],
                response_body_sha256=diagnostic["raw_body_sha256"],
                diagnostic_sha256=diagnostic["diagnostic_sha256"],
                diagnostic_event=X_CREATE_RESPONSE_ANOMALY_EVENT,
            )
            if json_error is not None:
                raise error from json_error
            raise error

        if is_post_create and not raw_create_body:
            log.debug("X tweet-create response has empty body")
            raise_create_response_anomaly(
                "empty_response_body",
                json_decode_succeeded=False,
                decoded=None,
            )
        if not is_post_create and not response.text:
            log.debug("X response has empty body")
            return {}

        try:
            data = response.json()
        except json.JSONDecodeError as e:
            if is_post_create:
                raise_create_response_anomaly(
                    "json_decode_error",
                    json_decode_succeeded=False,
                    decoded=None,
                    json_error=e,
                )
            log.error(
                "X API returned non-JSON response: %s",
                response.text[:1000],
            )
            if ambiguous_write:
                raise AmbiguousRemotePostOutcome(
                    "X may have accepted the write but returned a non-JSON "
                    f"response: {response.text[:500]}",
                    service="x",
                    request_method=method,
                    request_path=path,
                ) from e
            raise ApiError(
                f"X API returned non-JSON response: {response.text[:500]}",
                service="x",
                request_method=method,
                request_path=path,
            ) from e
        if not isinstance(data, dict):
            if is_post_create:
                raise_create_response_anomaly(
                    "decoded_top_level_not_object",
                    json_decode_succeeded=True,
                    decoded=data,
                )
            message = (
                "X API response must be a JSON object, got "
                f"{type(data).__name__}"
            )
            if ambiguous_write:
                raise AmbiguousRemotePostOutcome(
                    "X may have accepted the write but its response was not "
                    f"a JSON object: {type(data).__name__}",
                    service="x",
                    request_method=method,
                    request_path=path,
                )
            raise ApiError(
                message,
                service="x",
                request_method=method,
                request_path=path,
            )

        if is_post_create:
            anomaly_reason = x_create_response_anomaly_reason(data)
            if anomaly_reason is not None:
                raise_create_response_anomaly(
                    anomaly_reason,
                    json_decode_succeeded=True,
                    decoded=data,
                )

        log_json_debug("X response json", data)
        return data

    try:
        return process_received_response()
    finally:
        escaping_error = sys.exc_info()[1]
        if rejection_proof is not None:
            preserve_proof = False
            try:
                preserve_proof = bool(
                    isinstance(
                        escaping_error,
                        ProvedRemotePostNonSuccess,
                    )
                    and getattr(
                        escaping_error,
                        "remote_non_success_proof",
                        None,
                    )
                    is rejection_proof
                )
            except BaseException:
                preserve_proof = False
            if not preserve_proof:
                invalidate_reply_create_rejection_proof(rejection_proof)


def x_bearer_request(method: str, path: str, **kwargs) -> dict:
    """Send a bearer-authenticated X API request with bounded retries."""
    if str(method).upper() not in {"GET", "HEAD", "OPTIONS"}:
        raise AmbiguousRemotePostOutcome(
            "Bearer-authenticated X writes have no durable transaction authority",
            service="x",
            request_method=method,
            request_path=path,
        )
    if not X_BEARER_TOKEN:
        raise ApiError("X_BEARER_TOKEN is not set", service="x")

    url = f"{X_BASE}{path}"

    log.debug("X bearer request: %s %s", method, url)

    if "params" in kwargs:
        log_json_debug("X bearer request params", kwargs["params"])

    report_bot_health_progress("x_read")
    try:
        response = requests.request(
            method,
            url,
            headers={
                "Authorization": f"Bearer {X_BEARER_TOKEN}",
            },
            timeout=request_timeout(),
            **kwargs,
        )
    except requests.RequestException as e:
        log.exception("X bearer request failed before receiving response")
        raise ApiError(
            str(e),
            service="x",
            request_method=method,
            request_path=path,
        ) from e
    finally:
        report_bot_health_progress("x_read")

    log.debug("X bearer response status: %s", response.status_code)
    log.debug(
        "X bearer response headers: x-rate-limit-limit=%s remaining=%s reset=%s",
        response.headers.get("x-rate-limit-limit"),
        response.headers.get("x-rate-limit-remaining"),
        response.headers.get("x-rate-limit-reset"),
    )

    if response.status_code >= 400:
        log.error("X bearer API error %s: %s", response.status_code, response.text)
        reset_epoch = print_rate_limit_headers(response)

        raise ApiError(
            f"X bearer API error {response.status_code}: {response.text}",
            service="x",
            status_code=response.status_code,
            reset_epoch=reset_epoch,
            request_method=method,
            request_path=path,
        )

    if not response.text:
        return {}

    try:
        data = response.json()
    except json.JSONDecodeError as e:
        log.error("X bearer API returned non-JSON response: %s", response.text[:1000])
        raise ApiError(
            f"X bearer API returned non-JSON response: {response.text[:500]}",
            service="x",
            request_method=method,
            request_path=path,
        ) from e
    if not isinstance(data, dict):
        raise ApiError(
            f"X bearer API response must be a JSON object, got {type(data).__name__}",
            service="x",
            request_method=method,
            request_path=path,
        )

    log_json_debug("X bearer response json", data)
    return data


def x_quote_lookup_request(path: str, params: dict) -> dict:
    """
    The quote_tweets lookup is documented using Bearer auth. If X_BEARER_TOKEN
    is set, use it. Otherwise try the same OAuth1 path used by the rest of
    this bot.
    """
    if X_BEARER_TOKEN:
        return x_bearer_request("GET", path, params=params)

    log.warning("X_BEARER_TOKEN not set; trying quote lookup with OAuth1")
    return x_request("GET", path, params=params)


def api_error_is_invalid_pagination_cursor(error: BaseException) -> bool:
    """Recognise only X 400 responses which specifically reject a cursor."""
    if not isinstance(error, ApiError):
        return False
    if error.service != "x" or error.status_code != 400:
        return False
    message = str(error)
    candidate_messages: list[str] = []
    json_start = message.find("{")
    if json_start >= 0:
        try:
            payload = json.loads(message[json_start:])
        except (json.JSONDecodeError, TypeError, ValueError):
            payload = None
        if isinstance(payload, dict):
            errors = payload.get("errors")
            if isinstance(errors, dict):
                errors = [errors]
            if isinstance(errors, list):
                for item in errors:
                    if not isinstance(item, dict):
                        continue
                    for key in ("message", "detail", "reason"):
                        value = item.get(key)
                        if isinstance(value, str):
                            candidate_messages.append(value)
            for key in ("message", "detail", "reason"):
                value = payload.get(key)
                if isinstance(value, str):
                    candidate_messages.append(value)
            if not candidate_messages:
                return False
    if not candidate_messages:
        candidate_messages = [message]

    def explicitly_rejects_cursor(candidate: str) -> bool:
        candidate = candidate.casefold()
        names_cursor = any(
            marker in candidate
            for marker in (
                "pagination_token",
                "pagination token",
                "next_token",
                "next token",
                "pagination cursor",
            )
        )
        rejects_cursor = any(
            marker in candidate
            for marker in (
                "invalid",
                "expired",
                "malformed",
                "not valid",
                "not recognised",
                "not recognized",
            )
        )
        return names_cursor and rejects_cursor

    return any(explicitly_rejects_cursor(item) for item in candidate_messages)


def x_paginated_get(
    request_func,
    path: str,
    params: dict,
    *,
    max_pages: int,
    label: str,
    on_invalid_cursor=None,
    on_repeated_cursor=None,
    on_page=None,
    should_request_cursor=None,
    initial_requested_tokens: set[str] | None = None,
    retry_invalid_cursor_from_head: bool = True,
) -> dict:
    """
    Read bounded pages from an X API collection endpoint.

    A cursor-specific HTTP 400 gets one recovery from the original collection
    head. The caller clears its durable saved cursor before that retry. Other
    client errors remain fail-closed. Every validated page is passed to
    ``on_page`` before a repeated returned token terminates traversal. By
    default the repeated token is then rejected before it can be requested
    twice. A caller may instead supply ``on_repeated_cursor`` to retain the
    bounded partial result and stop normally. ``should_request_cursor`` may
    optionally stop before a continuation request as a bounded partial success.
    """
    base_params = dict(params)
    recovered_invalid_cursor = False
    cursor_state_invalidated = False
    requested_tokens: set[str] = set(initial_requested_tokens or set())
    repeated_token_detected = False
    cursor_request_suppressed = False

    def invalidate_cursor_state() -> None:
        nonlocal cursor_state_invalidated
        if cursor_state_invalidated:
            return
        if on_invalid_cursor is not None:
            on_invalid_cursor()
        cursor_state_invalidated = True

    while True:
        combined: dict[str, object] = {"data": []}
        users_by_id: dict[str, dict] = {}
        media_by_key: dict[str, dict] = {}
        next_token = ""
        pages_fetched = 0
        restart_from_head = False

        for page in range(1, max(1, int(max_pages)) + 1):
            page_params = dict(base_params)
            if next_token:
                page_params["pagination_token"] = next_token
            request_token = str(page_params.get("pagination_token") or "")
            if request_token:
                if request_token in requested_tokens:
                    if on_repeated_cursor is None:
                        invalidate_cursor_state()
                        raise PaginationCursorProtocolError(
                            f"X {label} repeated pagination token before request",
                            service="x",
                        )
                    on_repeated_cursor(
                        request_token,
                        pages_fetched,
                        len(combined["data"]),
                    )
                    repeated_token_detected = True
                    next_token = ""
                    break
                if (
                    should_request_cursor is not None
                    and not should_request_cursor(request_token)
                ):
                    cursor_request_suppressed = True
                    next_token = ""
                    break
                requested_tokens.add(request_token)

            try:
                result = request_func(path, page_params)
            except ApiError as exc:
                if (
                    request_token
                    and not recovered_invalid_cursor
                    and api_error_is_invalid_pagination_cursor(exc)
                ):
                    invalidate_cursor_state()
                    if not retry_invalid_cursor_from_head:
                        raise
                    recovered_invalid_cursor = True
                    base_params.pop("pagination_token", None)
                    restart_from_head = True
                    log.warning(
                        "X %s rejected a pagination cursor; cleared the saved "
                        "cursor and retrying once from the collection head",
                        label,
                    )
                    break
                raise

            if not isinstance(result, dict):
                raise ApiError(f"X {label} returned a malformed paginated response object", service="x")
            page_data = result.get("data", [])
            includes = result.get("includes", {})
            meta = result.get("meta", {})
            if not isinstance(page_data, list) or any(not isinstance(item, dict) for item in page_data):
                raise ApiError(f"X {label} returned malformed paginated response data", service="x")
            if not isinstance(includes, dict):
                raise ApiError(f"X {label} returned malformed paginated response includes", service="x")
            users = includes.get("users", [])
            media_items = includes.get("media", [])
            if not isinstance(users, list) or any(not isinstance(user, dict) for user in users):
                raise ApiError(f"X {label} returned malformed paginated response users", service="x")
            if not isinstance(media_items, list) or any(not isinstance(media, dict) for media in media_items):
                raise ApiError(f"X {label} returned malformed paginated response media", service="x")
            if not isinstance(meta, dict):
                raise ApiError(f"X {label} returned malformed paginated response meta", service="x")
            pages_fetched = page
            combined["data"].extend(page_data)

            for user in users:
                user_id = str(user.get("id", ""))
                if user_id:
                    users_by_id[user_id] = user

            for media in media_items:
                media_key = str(media.get("media_key", ""))
                if media_key:
                    media_by_key[media_key] = media

            next_token = str(meta.get("next_token", "") or "")
            log.info(
                "Fetched %s page %d/%d items=%d next_token=%s",
                label,
                page,
                max_pages,
                len(page_data) if isinstance(page_data, list) else 0,
                bool(next_token),
            )
            if on_page is not None:
                on_page(
                    page_data,
                    includes,
                    next_token,
                    request_token,
                    pages_fetched,
                )
            if next_token and next_token in requested_tokens:
                if on_repeated_cursor is None:
                    invalidate_cursor_state()
                    raise PaginationCursorProtocolError(
                        f"X {label} returned a repeated pagination token",
                        service="x",
                    )
                on_repeated_cursor(
                    next_token,
                    pages_fetched,
                    len(combined["data"]),
                )
                repeated_token_detected = True
                next_token = ""
                break
            if not next_token:
                break

        if restart_from_head:
            continue
        break

    includes: dict[str, list[dict]] = {}
    if users_by_id:
        includes["users"] = list(users_by_id.values())
    if media_by_key:
        includes["media"] = list(media_by_key.values())
    if includes:
        combined["includes"] = includes
    combined["_pagination"] = {
        "pages_fetched": pages_fetched,
        "truncated": (
            bool(next_token)
            or repeated_token_detected
            or cursor_request_suppressed
        ),
        "next_token": next_token or None,
        "invalid_cursor_recovered": recovered_invalid_cursor,
        "repeated_token_detected": repeated_token_detected,
    }
    if cursor_request_suppressed:
        combined["_pagination"]["cursor_request_suppressed"] = True
    if next_token:
        pagination_log = log.info if label == "mentions" else log.warning
        pagination_log(
            "Pagination truncated for %s after %d page(s); more results remain",
            label,
            pages_fetched,
        )

    return combined


# ---------------------------------------------------------------------
# Tweet cache / thread context
# ---------------------------------------------------------------------

def prune_tweet_cache(state: dict) -> None:
    """Prune tweet cache."""
    cache = state.setdefault("tweet_cache", {})
    cutoff = now_epoch() - TWEET_CACHE_MAX_AGE_SECONDS

    pruned = {
        str(tweet_id): tweet
        for tweet_id, tweet in cache.items()
        if int(tweet.get("cached_epoch", 0) or 0) >= cutoff
    }

    if len(pruned) > TWEET_CACHE_MAX_ITEMS:
        items = sorted(
            pruned.items(),
            key=lambda kv: int(kv[1].get("cached_epoch", 0) or 0),
            reverse=True,
        )
        pruned = dict(items[:TWEET_CACHE_MAX_ITEMS])

    if len(pruned) != len(cache):
        log.info("Pruned tweet cache from %d to %d items", len(cache), len(pruned))

    state["tweet_cache"] = pruned


def record_recent_own_post(state: dict, tweet_id: str) -> None:
    """Record recent own post."""
    tweet_id = str(tweet_id)

    ids = [str(x) for x in state.get("recent_own_post_ids", []) if str(x) != tweet_id]
    ids.insert(0, tweet_id)
    state["recent_own_post_ids"] = ids[:RECENT_OWN_POST_IDS_MAX]

    log.info("Recorded recent own post id=%s recent_count=%d", tweet_id, len(state["recent_own_post_ids"]))


def seed_recent_own_post_ids_from_cache(state: dict) -> None:
    """Seed recent own post IDs from cache."""
    if state.get("recent_own_post_ids"):
        return

    cache = state.get("tweet_cache", {})
    own_posts: list[tuple[int, str]] = []

    for tweet_id, tweet in cache.items():
        if str(tweet.get("author_id")) != str(MY_USER_ID):
            continue

        post_type = tweet.get("post_type")
        if post_type not in {"quote", "daily_meme"}:
            continue

        own_posts.append((int(tweet.get("cached_epoch", 0) or 0), str(tweet_id)))

    own_posts.sort(reverse=True)
    seeded = [tweet_id for _, tweet_id in own_posts[:RECENT_OWN_POST_IDS_MAX]]

    if not seeded and state.get("last_main_post_id"):
        seeded = [str(state["last_main_post_id"])]

    state["recent_own_post_ids"] = seeded
    log.info("Seeded recent_own_post_ids from cache count=%d", len(seeded))


def cache_tweet(
    state: dict,
    *,
    tweet_id: str,
    text: str,
    author_id: str,
    conversation_id: str | None = None,
    referenced_tweets: list[dict] | None = None,
    created_at: str | None = None,
    image_summary: str | None = None,
    post_type: str | None = None,
) -> dict:
    """Return the cache tweet."""
    prune_tweet_cache(state)

    tweet_id = str(tweet_id)
    cache = state.setdefault("tweet_cache", {})

    cached_tweet = {
        "id": tweet_id,
        "author_id": str(author_id),
        "conversation_id": str(conversation_id or tweet_id),
        "created_at": created_at or current_datetime().isoformat(),
        "referenced_tweets": referenced_tweets or [],
        "text": text or "",
        "cached_epoch": now_epoch(),
    }

    if image_summary:
        cached_tweet["image_summary"] = image_summary

    if post_type:
        cached_tweet["post_type"] = post_type

    normalised_tweet = normalise_tweet_cache_entry(tweet_id, cached_tweet, path=STATE_FILE)
    if normalised_tweet is None:
        raise ValueError(f"Refusing to cache malformed tweet entry id={tweet_id}")

    cached_tweet = normalised_tweet
    cache[tweet_id] = cached_tweet
    state["tweet_cache"] = cache

    log.info(
        "Cached tweet id=%s author_id=%s cache_size=%d post_type=%s image_summary=%s",
        tweet_id,
        author_id,
        len(cache),
        post_type or "",
        bool(image_summary),
    )

    return cached_tweet


def get_immediate_parent_id(tweet: dict) -> str | None:
    """Return immediate parent ID."""
    referenced_tweets = tweet.get("referenced_tweets", [])
    if referenced_tweets is None:
        return None
    if not isinstance(referenced_tweets, list):
        raise ApiError("X tweet returned malformed referenced_tweets", service="x")

    for ref in referenced_tweets:
        if not isinstance(ref, dict):
            raise ApiError("X tweet returned malformed referenced_tweets", service="x")
        if ref.get("type") == "replied_to":
            parent_id = parse_tweet_id(ref.get("id"), context="parent reference")
            if parent_id is None:
                raise ApiError("X tweet returned malformed referenced_tweets", service="x")
            return str(parent_id)

    return None


def get_tweet_by_id(tweet_id: str) -> dict | None:
    """Fetch one post from X by ID."""
    log.info("Fetching tweet by id. tweet_id=%s", tweet_id)

    params = {
        "tweet.fields": "author_id,created_at,conversation_id,referenced_tweets",
    }

    result = x_request(
        "GET",
        f"/2/tweets/{tweet_id}",
        params=params,
    )

    tweet = result.get("data")
    if tweet is not None and not isinstance(tweet, dict):
        raise ApiError("X tweet lookup returned malformed tweet data", service="x")
    log_json_debug("Fetched tweet", tweet)

    return tweet


def reply_target_is_available_immediately_before_send(target_id: str) -> bool:
    """Freshly prove that one reply target still exists before durable send setup.

    Reply generation can take long enough for a fetched mention or quote tweet
    to be deleted in the meantime.  A direct lookup here deliberately bypasses
    the tweet cache and runs before the sending receipt and transport journal
    are created.  Target-specific lookup failures are terminal for this
    candidate; authentication, endpoint and transient failures remain errors
    so callers retain the approved draft for a later attempt.
    """

    target_id = str(target_id)
    log.info(
        "Freshly revalidating reply target immediately before send. target_id=%s",
        target_id,
    )
    try:
        target = get_tweet_by_id(target_id)
    except ApiError as exc:
        if api_error_is_permanent_target_failure(exc):
            log.warning(
                "Reply target became unavailable before send. target_id=%s",
                target_id,
            )
            return False
        raise

    if target is None:
        log.warning(
            "Reply target was absent in the fresh pre-send lookup. target_id=%s",
            target_id,
        )
        return False
    if not isinstance(target, dict) or str(target.get("id") or "") != target_id:
        raise ApiError(
            "X reply-target pre-send lookup returned a mismatched or malformed post",
            service="x",
            request_method="GET",
            request_path=f"/2/tweets/{target_id}",
        )

    log.info("Fresh pre-send reply-target lookup passed. target_id=%s", target_id)
    return True


def get_tweet_by_id_cached(tweet_id: str, state: dict) -> dict | None:
    """Return a cached post or fetch it from X by ID."""
    prune_tweet_cache(state)

    tweet_id = str(tweet_id)
    cache = state.setdefault("tweet_cache", {})
    cached = cache.get(tweet_id)

    if cached:
        log.info("Using cached tweet for context. tweet_id=%s", tweet_id)
        return cached

    tweet = get_tweet_by_id(tweet_id)

    if tweet:
        cached_tweet = cache_tweet(
            state,
            tweet_id=str(tweet.get("id", tweet_id)),
            text=tweet.get("text", ""),
            author_id=str(tweet.get("author_id", "")),
            conversation_id=str(tweet.get("conversation_id", tweet_id)),
            referenced_tweets=tweet.get("referenced_tweets", []),
            created_at=tweet.get("created_at"),
        )
        save_state(state)
        return cached_tweet

    return None


def clean_text_for_reply_context(text: str) -> str:
    """Return normalised text for a bounded AI reply context."""
    text = html.unescape(text or "")
    text = re.sub(r"https?://\S+", "", text)
    text = " ".join(text.split())
    return text.strip()


def attach_media_to_tweets(tweets: list[dict], includes: dict | None) -> None:
    """Attach media to tweets."""
    media_items = (includes or {}).get("media", [])
    if not isinstance(media_items, list):
        return

    media_by_key = {
        str(media.get("media_key")): media
        for media in media_items
        if isinstance(media, dict) and media.get("media_key")
    }
    if not media_by_key:
        return

    for tweet in tweets:
        attachments = tweet.get("attachments", {})
        if not isinstance(attachments, dict):
            continue
        media_keys = attachments.get("media_keys", [])
        if not isinstance(media_keys, list):
            continue
        attached = [
            media_by_key[str(media_key)]
            for media_key in media_keys
            if str(media_key) in media_by_key
        ]
        if attached:
            tweet["_attached_media"] = attached


def candidate_native_photo_media(candidate: dict) -> tuple[list[dict], int]:
    """Return the candidate native photo media."""
    media_items = candidate.get("_attached_media", [])
    if not isinstance(media_items, list):
        media_items = []

    photo_records = [
        media
        for media in media_items
        if isinstance(media, dict) and str(media.get("type", "")).lower() == "photo"
    ]
    usable: list[dict] = []
    for media in photo_records:
        url = str(media.get("url") or "").strip()
        if not url:
            continue
        usable.append(
            {
                "media_key": str(media.get("media_key", "")),
                "url": url,
            }
        )
        if len(usable) >= MAX_REPLY_CONTEXT_PHOTOS:
            break

    return usable, len(photo_records)


def reply_media_context_for_candidate(candidate: dict, *, lane: str, target_id: str) -> dict:
    """Return the reply media context for candidate."""
    photos, expected_photo_count = candidate_native_photo_media(candidate)
    if photos:
        log.info(
            "Reply media context lane=%s target_id=%s photos=%d mode=multimodal status=supplied",
            lane,
            target_id,
            len(photos),
        )
        return {
            "lane": lane,
            "target_id": str(target_id),
            "mode": "multimodal",
            "status": "supplied",
            "photos_expected": expected_photo_count,
            "photos": photos,
        }

    if expected_photo_count:
        log.warning(
            "Reply media context unavailable lane=%s target_id=%s photos_expected=%d mode=multimodal status=unavailable",
            lane,
            target_id,
            expected_photo_count,
        )
        return {
            "lane": lane,
            "target_id": str(target_id),
            "mode": "multimodal",
            "status": "unavailable",
            "photos_expected": expected_photo_count,
            "photos": [],
        }

    return {
        "lane": lane,
        "target_id": str(target_id),
        "mode": "none",
        "status": "none",
        "photos_expected": 0,
        "photos": [],
    }


def redact_xai_payload_for_log(payload: dict) -> dict:
    """Redact xAI payload for log."""
    redacted = copy.deepcopy(payload)
    for message in redacted.get("messages", []) or []:
        content = message.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict) or part.get("type") != "image_url":
                continue
            image_url = part.get("image_url")
            if isinstance(image_url, dict) and image_url.get("url"):
                image_url["url"] = "[redacted native X image URL]"
    return redacted


def tweet_context_text(tweet: dict) -> str:
    """Return the tweet context text."""
    cleaned = clean_text_for_reply_context(tweet.get("text", ""))

    if cleaned:
        return cleaned

    image_summary = clean_text_for_reply_context(tweet.get("image_summary", ""))
    if image_summary:
        return f"[Image/meme summary: {image_summary}]"

    return ""


def trim_context_text(text: str, max_chars: int) -> str:
    """Trim context text."""
    text = clean_text_for_reply_context(text)

    if max_chars <= 0:
        return ""
    if len(text) <= max_chars:
        return text
    if max_chars <= 3:
        return text[:max_chars]
    prefix = text[:max_chars - 3].rsplit(" ", 1)[0].rstrip(".,;:")
    if not prefix:
        prefix = text[:max_chars - 3]
    return prefix + "..."


def build_parent_chain(mention: dict, state: dict) -> list[dict]:
    """Build bounded earlier-thread context for a reply candidate."""
    chain: list[dict] = []
    seen_ids: set[str] = set()

    parent_id = get_immediate_parent_id(mention)

    while parent_id and len(chain) < THREAD_CONTEXT_MAX_DEPTH:
        if parent_id in seen_ids:
            log.warning("Detected parent-chain loop at tweet_id=%s", parent_id)
            break

        seen_ids.add(parent_id)

        try:
            parent = get_tweet_by_id_cached(parent_id, state)
        except ApiError as exc:
            if api_error_is_permanent_target_failure(exc):
                log.warning(
                    "Parent tweet_id=%s is permanently unavailable with status=%s; continuing without it",
                    parent_id,
                    getattr(exc, "status_code", None),
                )
                break
            raise
        if not parent:
            log.info("Could not fetch/cache parent tweet_id=%s", parent_id)
            break

        chain.append(parent)
        parent_id = get_immediate_parent_id(parent)

    chain.reverse()
    log.info("Built parent chain with %d item(s)", len(chain))
    log_json_debug("Parent chain", chain)

    return chain


def _reply_context_order(tweet: dict) -> tuple[int, str]:
    """Return a stable chronological key for cached X posts."""
    tweet_id = str(tweet.get("id") or "")
    return (int(tweet_id) if tweet_id.isdigit() else 0, tweet_id)


def _author_cap_context_posts(mention: dict, state: dict) -> list[dict]:
    """Return cached cap-skipped contributions from this author and conversation."""
    mention_id = str(mention.get("id") or "")
    author_id = str(mention.get("author_id") or "")
    conversation_id = str(mention.get("conversation_id") or mention_id)
    cache = state.get("tweet_cache", {})
    if not isinstance(cache, dict):
        return []

    posts = [
        tweet
        for tweet_id, tweet in cache.items()
        if isinstance(tweet, dict)
        and str(tweet_id) != mention_id
        and tweet.get("post_type") in {"author_cap_context", "author_cap_quote_context"}
        and str(tweet.get("author_id") or "") == author_id
        and str(tweet.get("conversation_id") or tweet_id) == conversation_id
    ]
    return sorted(posts, key=_reply_context_order)


def _cached_quoted_post_for_cap_context(
    context_posts: list[dict],
    state: dict,
) -> dict[str, str] | None:
    """Recover a capped quote-tweet's original post without an X lookup."""
    cache = state.get("tweet_cache", {})
    if not isinstance(cache, dict):
        return None

    for tweet in reversed(context_posts):
        if tweet.get("post_type") != "author_cap_quote_context":
            continue
        references = tweet.get("referenced_tweets", []) or []
        for reference in references:
            if not isinstance(reference, dict) or reference.get("type") != "quoted":
                continue
            quoted_id = str(reference.get("id") or "")
            quoted = cache.get(quoted_id)
            if not isinstance(quoted, dict):
                return {
                    "post_id": quoted_id or "unknown",
                    "author_role": "unknown",
                    "text": "[Quoted post unavailable.]",
                }
            return _reply_context_post(
                quoted,
                maximum_chars=THREAD_CONTEXT_MAX_CHARS_PER_POST,
            )
    return None


def is_our_auto_reply(tweet: dict | None, state: dict) -> bool:
    """Return whether is our auto reply."""
    if not tweet:
        return False

    if str(tweet.get("author_id")) != str(MY_USER_ID):
        return False

    own_auto_reply_ids = set(str(x) for x in state.get("own_auto_reply_ids", []))
    return str(tweet.get("id")) in own_auto_reply_ids


def _reply_context_post(tweet: dict, *, maximum_chars: int) -> dict[str, str]:
    """Return one bounded post with an explicit role label."""
    author_id = str(tweet.get("author_id") or "")
    if author_id == str(MY_USER_ID):
        author_role = "account"
    elif author_id:
        author_role = "user"
    else:
        author_role = "unknown"
    return {
        "post_id": str(tweet.get("id") or "unknown"),
        "author_role": author_role,
        "text": trim_context_text(tweet_context_text(tweet), maximum_chars),
    }


def _quoted_post_for_reply_context(candidate: dict, state: dict) -> dict[str, str] | None:
    """Return one explicitly quoted post, including an unavailable marker when known."""
    references = candidate.get("referenced_tweets", []) or []
    for reference in references:
        if not isinstance(reference, dict) or reference.get("type") != "quoted":
            continue
        quoted_id = str(reference.get("id") or "")
        if not quoted_id:
            continue
        try:
            quoted = get_tweet_by_id_cached(quoted_id, state)
        except ApiError as exc:
            if not api_error_is_permanent_target_failure(exc):
                raise
            quoted = None
        if quoted is None:
            return {
                "post_id": quoted_id,
                "author_role": "unknown",
                "text": "[Quoted post unavailable.]",
            }
        return _reply_context_post(
            quoted,
            maximum_chars=THREAD_CONTEXT_MAX_CHARS_PER_POST,
        )
    return None


def build_context_for_reply_ai(mention: dict, state: dict) -> tuple[dict[str, object], bool]:
    """Build structured incoming, parent-thread and quoted-post context."""
    mention_id = str(mention.get("id"))
    mention_text = mention.get("text", "").strip()

    if not mention_text:
        log.info("Mention %s has no text; skipping", mention_id)
        return {}, False

    chain: list[dict] = []

    if ALWAYS_FETCH_PARENT_FOR_CONTEXT:
        try:
            chain = build_parent_chain(mention, state)
        except ApiError as e:
            log.warning("Could not build parent chain for mention %s: %s", mention_id, e)
            raise
        except Exception as e:
            log.warning("Unexpected failure building parent chain for mention %s: %s", mention_id, e)
            return {}, False

    immediate_parent = chain[-1] if chain else None

    if SKIP_REPLIES_TO_OWN_AUTO_REPLIES and is_our_auto_reply(immediate_parent, state):
        log.info(
            "Skipping mention %s: immediate parent %s is one of our own auto-replies",
            mention_id,
            immediate_parent.get("id") if immediate_parent else None,
        )
        return {}, False

    immediate_parent_id = str(immediate_parent.get("id") or "") if immediate_parent else ""
    merged_by_id: dict[str, dict] = {}
    for tweet in chain:
        tweet_id = str(tweet.get("id") or "")
        if tweet_id and tweet_id != mention_id:
            merged_by_id[tweet_id] = tweet
    complete_cap_context = _author_cap_context_posts(mention, state)
    recovered_cap_quoted_post = _cached_quoted_post_for_cap_context(
        complete_cap_context,
        state,
    )
    for tweet in complete_cap_context:
        tweet_id = str(tweet.get("id") or "")
        if tweet_id:
            merged_by_id[tweet_id] = tweet

    merged_context = sorted(merged_by_id.values(), key=_reply_context_order)
    selected_context = merged_context[-3:]
    if immediate_parent_id and all(
        str(tweet.get("id") or "") != immediate_parent_id for tweet in selected_context
    ):
        selected_context = sorted(
            [immediate_parent, *selected_context[-2:]],
            key=_reply_context_order,
        )

    # The AI-first context contract permits at most three inherited posts. Prefer the newest
    # relevant context, retain the immediate parent, and enforce the aggregate text budget.
    remaining_parent_chars = min(max(int(THREAD_CONTEXT_MAX_TOTAL_CHARS), 0), 6_000)
    maximum_parent_chars = min(max(int(THREAD_CONTEXT_MAX_CHARS_PER_POST), 0), 2_000)
    parent_thread: list[dict[str, str]] = []
    for tweet in reversed(selected_context):
        post = _reply_context_post(
            tweet,
            maximum_chars=min(maximum_parent_chars, remaining_parent_chars),
        )
        remaining_parent_chars -= len(post["text"])
        parent_thread.insert(0, post)
    context: dict[str, object] = {
        "target_id": mention_id,
        "thread_id": str(mention.get("conversation_id") or mention_id),
        "lane": str(mention.get("_source") or "mention"),
        "incoming_contribution": trim_context_text(mention_text, REPLY_INCOMING_MAX_CHARS),
        "quoted_post": (
            _quoted_post_for_reply_context(mention, state)
            or recovered_cap_quoted_post
        ),
        "parent_thread": parent_thread,
        "clarification_request": None,
        "current_date": current_datetime().strftime("%Y-%m-%d"),
    }

    log.info(
        "Built AI reply context for mention %s. chain_items=%d immediate_parent=%s quoted=%s",
        mention_id,
        len(chain),
        immediate_parent.get("id") if immediate_parent else None,
        bool(context["quoted_post"]),
    )
    log_json_debug("Context sent to AI reply pipeline", context)

    return context, True


# ---------------------------------------------------------------------
# Mentions
# ---------------------------------------------------------------------

def reply_target_is_directly_eligible(tweet: dict) -> bool:
    """Check only the target post itself for X reply eligibility evidence."""
    if str(tweet.get("author_id") or "") == str(MY_USER_ID):
        return True

    entities = tweet.get("entities")
    if isinstance(entities, dict):
        mentions = entities.get("mentions")
        if isinstance(mentions, list):
            for mention in mentions:
                if not isinstance(mention, dict):
                    continue
                if str(mention.get("id") or "") == str(MY_USER_ID):
                    return True
                username = str(mention.get("username") or "").lstrip("@")
                if MY_USERNAME and username.casefold() == MY_USERNAME.casefold():
                    return True
        return False

    text = str(tweet.get("text") or "")
    if MY_USERNAME and re.search(
        rf"(?<![A-Za-z0-9_])@{re.escape(MY_USERNAME)}(?![A-Za-z0-9_])",
        text,
        flags=re.IGNORECASE,
    ):
        return True
    return False


def pending_mention_candidates(state: dict) -> list[dict]:
    """Return the durable fetched-candidate queue, deduplicated by status ID."""
    usable, changed = validate_pending_mention_candidate_authority(
        state,
        path=STATE_FILE,
        recover_pending_identity=True,
    )
    if not usable:
        raise RuntimeError(
            "Mention pending-candidate authority cannot be recovered without "
            "a bounded watermark"
        )
    if changed:
        save_state(state, durable=True)
    pending = state.get("mention_pending_candidates", {})
    if not isinstance(pending, dict):
        return []
    return valid_tweets_sorted_by_id(
        list(pending.values()),
        context="durable pending mention",
    )


def remove_pending_mention_candidate(state: dict, mention_id: str) -> bool:
    """Remove one completely handled mention from the durable fetched queue."""
    pending = state.get("mention_pending_candidates")
    if not isinstance(pending, dict) or str(mention_id) not in pending:
        return False
    pending = dict(pending)
    pending.pop(str(mention_id), None)
    state["mention_pending_candidates"] = pending
    return True


def get_mentions(state: dict) -> list[dict]:
    """Fetch, durably queue and resume bounded pages of direct mentions.

    A fetched page is saved before its cursor or completed-range watermark is
    committed.  The durable pending queue therefore owns candidates until the
    reply loop records each one as handled, including across process restarts.
    """
    queued = pending_mention_candidates(state)
    if queued:
        log.info("Using %d durably queued mention candidate(s) before further pagination", len(queued))
        return queued

    current = now_epoch()
    remaining_pages = max(1, int(MENTIONS_MAX_PAGES_PER_CHECK))
    reset_logged = False

    def reset_backlog(reason: str, *, token: str = "") -> None:
        nonlocal reset_logged
        backlog = state.get("mention_backlog", {})
        saved_since_id = (
            str(backlog.get("since_id", ""))
            if isinstance(backlog, dict)
            else str(state.get("last_seen_mention_id") or "")
        )
        pages_completed = (
            int(backlog.get("pages_completed", 0) or 0)
            if isinstance(backlog, dict)
            else 0
        )
        pending = state.get("mention_pending_candidates")
        discarded_candidates = len(pending) if isinstance(pending, dict) else 0
        state["mention_backlog_reset_guard"] = {
            "base_since_id": str(state.get("last_seen_mention_id") or ""),
            "head_traversal_started": False,
        }
        state["mention_backlog"] = {}
        state["mention_pagination"] = {}
        state["mention_pending_candidates"] = {}
        save_state(state, durable=True)
        if not reset_logged:
            log.warning(
                "Mention backlog continuation was reset reason=%s; watermark "
                "remains unchanged and %d pending candidate(s) were discarded",
                reason,
                discarded_candidates,
            )
            log_event(
                "mention_backlog_reset",
                reason=reason,
                since_id=saved_since_id or None,
                pages_completed=pages_completed,
                token_fingerprint=(
                    hashlib.sha256(token.encode("utf-8")).hexdigest()[:16]
                    if token
                    else None
                ),
            )
            reset_logged = True

    while remaining_pages > 0:
        watermark = str(state.get("last_seen_mention_id") or "")
        backlog = state.get("mention_backlog", {})
        if not isinstance(backlog, dict):
            backlog = {}

        # Migrate the exact legacy cursor retained by schema-v3/v4 reply
        # receipts into the richer traversal record on first use.
        legacy = state.get("mention_pagination", {})
        if not backlog and isinstance(legacy, dict):
            legacy_base = str(legacy.get("base_since_id", ""))
            legacy_token = str(legacy.get("next_token", "") or "")
            if legacy_token and legacy_base == watermark:
                backlog = {
                    "since_id": watermark,
                    "next_token": legacy_token,
                    "highest_mention_id": watermark,
                    "pages_completed": 0,
                    "started_epoch": current,
                    "seen_tokens": [],
                    "announced": True,
                }
                state["mention_backlog"] = backlog
                save_state(state, durable=True)

        if backlog and str(backlog.get("since_id", "")) != watermark:
            reset_backlog("since_id_mismatch")
            backlog = {}

        if not backlog:
            backlog = {
                "since_id": watermark,
                "next_token": "",
                "highest_mention_id": watermark,
                "pages_completed": 0,
                "started_epoch": current,
                "seen_tokens": [],
                "announced": False,
            }
            state["mention_backlog"] = backlog
            state["mention_pagination"] = {}
            reset_guard = active_mention_backlog_reset_guard(state)
            if reset_guard is not None and not reset_guard["head_traversal_started"]:
                state["mention_backlog_reset_guard"] = {
                    "base_since_id": watermark,
                    "head_traversal_started": True,
                }
            save_state(state, durable=True)

        base_since_id = str(backlog["since_id"])
        resume_token = str(backlog.get("next_token", "") or "")
        prior_seen_tokens = {
            str(token)
            for token in backlog.get("seen_tokens", [])
            if isinstance(token, str) and token
        }
        prior_pages_completed = int(backlog.get("pages_completed", 0) or 0)
        was_announced = bool(backlog.get("announced"))
        log.info(
            "Fetching mentions. since_id=%s resume=%s max_results=%s remaining_pages=%s",
            base_since_id or None,
            bool(resume_token),
            MAX_MENTIONS_PER_CHECK,
            remaining_pages,
        )

        params = {
            "max_results": MAX_MENTIONS_PER_CHECK,
            "tweet.fields": "author_id,created_at,conversation_id,referenced_tweets,attachments,entities",
            "expansions": "author_id,attachments.media_keys",
            "media.fields": "media_key,type,url,preview_image_url",
        }
        if base_since_id:
            params["since_id"] = base_since_id
        if resume_token:
            params["pagination_token"] = resume_token
            log.info("Resuming mention backlog from saved continuation token")

        traversal_completed = False
        traversal_added = 0
        completion_highest = str(backlog.get("highest_mention_id", "") or "")
        completion_pages = prior_pages_completed

        def persist_page(
            page_data: list[dict],
            includes: dict,
            next_token: str,
            request_token: str,
            _pages_this_call: int,
        ) -> None:
            nonlocal traversal_completed, traversal_added, completion_highest, completion_pages
            attach_media_to_tweets(page_data, includes)
            pending = state.get("mention_pending_candidates", {})
            if not isinstance(pending, dict):
                pending = {}
            pending = dict(pending)
            valid_page = valid_tweets_sorted_by_id(page_data, context="mention page")
            highest = str(
                state.get("mention_backlog", {}).get("highest_mention_id", "")
                if isinstance(state.get("mention_backlog"), dict)
                else ""
            )
            replied_ids = {
                str(value) for value in state.get("replied_to_ids", [])
            }
            for mention in valid_page:
                mention_id = str(mention["id"])
                if (
                    mention_id not in replied_ids
                    and terminal_reply_evaluation(state, mention_id) is None
                ):
                    pending.setdefault(mention_id, copy.deepcopy(mention))
                traversal_added += 1
                if not highest or int(mention_id) > int(highest):
                    highest = mention_id
                cache_tweet(
                    state,
                    tweet_id=mention_id,
                    text=mention.get("text", ""),
                    author_id=str(mention.get("author_id", "")),
                    conversation_id=str(mention.get("conversation_id", mention_id)),
                    referenced_tweets=mention.get("referenced_tweets", []),
                    created_at=mention.get("created_at"),
                )
            state["mention_pending_candidates"] = pending
            active = state.get("mention_backlog", {})
            if not isinstance(active, dict) or not active:
                raise RuntimeError("Mention backlog disappeared while persisting a fetched page")
            active = copy.deepcopy(active)
            seen_tokens = list(active.get("seen_tokens", []))
            if request_token and request_token not in seen_tokens:
                if len(seen_tokens) >= MENTION_BACKLOG_CONTINUATION_TOKEN_LIMIT:
                    reset_backlog(
                        "continuation_token_limit",
                        token=request_token,
                    )
                    raise _MentionBacklogContinuationLimit
                seen_tokens.append(request_token)
            active["seen_tokens"] = seen_tokens
            active["highest_mention_id"] = highest
            active["pages_completed"] = int(active.get("pages_completed", 0) or 0) + 1
            active["next_token"] = str(next_token or "")
            completion_highest = highest
            completion_pages = int(active["pages_completed"])
            if next_token:
                state["mention_backlog"] = active
                state["mention_pagination"] = {
                    "base_since_id": str(active["since_id"]),
                    "next_token": str(next_token),
                }
                save_state(state, durable=True)
                if active.get("announced"):
                    log_event(
                        "mention_backlog_progress",
                        since_id=active["since_id"] or None,
                        pages_completed=active["pages_completed"],
                        highest_mention_id=highest or None,
                        continuation_token_present=True,
                    )
                return

            reset_guard = active_mention_backlog_reset_guard(state)
            head_traversal_completed = bool(
                reset_guard is not None
                and reset_guard["head_traversal_started"]
            )
            if highest and (reset_guard is None or head_traversal_completed):
                update_last_seen_mention_id(state, highest)
            elif highest and reset_guard is not None:
                log.warning(
                    "Deferring mention watermark advancement after a reset "
                    "until a traversal from the collection head completes"
                )
            state["mention_backlog"] = {}
            state["mention_pagination"] = {}
            if head_traversal_completed:
                state["mention_backlog_reset_guard"] = {}
            prune_completed_mention_quarantine_evaluations(state)
            save_state(state, durable=True)
            traversal_completed = True
            if active.get("announced"):
                log_event(
                    "mention_backlog_completed",
                    since_id=active["since_id"] or None,
                    pages_completed=active["pages_completed"],
                    highest_mention_id=highest or None,
                    backlog_age_seconds=max(0, current - int(active["started_epoch"])),
                )

        def invalid_cursor() -> None:
            reset_backlog("invalid_continuation_token", token=resume_token)

        def repeated_cursor(token: str, pages: int, _results: int) -> None:
            pending = state.get("mention_pending_candidates")
            if pages > 0 and isinstance(pending, dict) and pending:
                log.warning(
                    "Mention backlog repeated its continuation token after a "
                    "persisted page; retaining pagination provenance until %d "
                    "pending candidate(s) are handled",
                    len(pending),
                )
                return
            reset_backlog("repeated_continuation_token", token=token)

        try:
            result = x_paginated_get(
                lambda path, page_params: x_request("GET", path, params=page_params),
                f"/2/users/{MY_USER_ID}/mentions",
                params,
                max_pages=remaining_pages,
                label="mentions",
                on_invalid_cursor=invalid_cursor,
                on_repeated_cursor=repeated_cursor,
                on_page=persist_page,
                initial_requested_tokens=prior_seen_tokens,
                retry_invalid_cursor_from_head=False,
            )
        except _MentionBacklogContinuationLimit:
            break
        except ApiError as exc:
            if resume_token and api_error_is_invalid_pagination_cursor(exc):
                break
            raise

        pagination = result.get("_pagination", {}) if isinstance(result.get("_pagination"), dict) else {}
        pages_fetched = int(pagination.get("pages_fetched", 0) or 0)
        remaining_pages = max(0, remaining_pages - pages_fetched)
        if pagination.get("repeated_token_detected"):
            break
        if pagination.get("truncated"):
            active = state.get("mention_backlog", {})
            next_token = str(pagination.get("next_token") or "")
            if not next_token or not isinstance(active, dict) or not active:
                reset_backlog("missing_continuation_token", token=next_token)
                break
            if not active.get("announced"):
                active = copy.deepcopy(active)
                active["announced"] = True
                state["mention_backlog"] = active
                save_state(state, durable=True)
                log_event(
                    "mention_backlog_started",
                    since_id=active["since_id"] or None,
                    pages_completed=active["pages_completed"],
                    highest_mention_id=active.get("highest_mention_id") or None,
                    continuation_token_present=True,
                    backlog_started_epoch=active["started_epoch"],
                )
            elif not was_announced or int(active.get("pages_completed", 0) or 0) == prior_pages_completed:
                log_event(
                    "mention_backlog_progress",
                    since_id=active["since_id"] or None,
                    pages_completed=active["pages_completed"],
                    highest_mention_id=active.get("highest_mention_id") or None,
                    continuation_token_present=True,
                )
            break

        if not traversal_completed or pages_fetched == 0:
            break
        # Only completion of a previously truncated traversal starts a new
        # range in the same check.  An ordinary completed traversal is already
        # the current range; immediately repeating it would refetch the same
        # leading page before its candidates have been retired.
        if (
            not resume_token
            or traversal_added == 0
            or not completion_highest
            or completion_pages <= 0
        ):
            break

    mentions = pending_mention_candidates(state)
    log.info("Fetched and durably queued %d mention candidate(s)", len(mentions))
    log_json_debug("Mentions returned", mentions)
    return mentions


def get_hot_post_reply_candidates(state: dict) -> list[dict]:
    """
    Fetch directly reply-eligible contributions in conversations for watched hot posts.

    This deliberately uses the same extra_quote_watch_post_ids.txt file as the
    quote-tweet watch lane, so adding one hot post ID makes both lanes watch it.
    X permits a reply only when this account authored or is directly mentioned
    in the target post. Organic sub-thread chatter is therefore terminally
    skipped before applying the candidate cap, while eligible candidates are
    marked with _source=hot_post_reply and passed through the normal reply path.

    A soft per-hot-post since_id watermark is used only after a search returns
    no usable candidates. That avoids repeatedly downloading the same dead
    results, while preserving response ability when there is anything actionable.
    A full rescan is forced every HOT_POST_REPLY_FULL_RESCAN_EVERY_CHECKS passes.
    """
    if not ENABLE_HOT_POST_REPLY_CHECKS:
        return []

    if lane_paused("disable_replies", "disable_hot_post_replies"):
        log.info("Skipping hot-post reply search due to runtime control file")
        return []

    if in_api_cooldown(state, scope="quote"):
        log.info("Skipping hot-post reply search due to quote API cooldown")
        return []

    try:
        watched_post_ids = load_extra_quote_watch_post_ids()
    except Exception as exc:
        log.warning("Could not load hot-post reply watch IDs: %s", exc)
        return []

    if not watched_post_ids:
        return []

    skipped_hot_reply_ids = set(str(x) for x in state.get("skipped_hot_reply_ids", []))
    replied_to_ids = set(str(x) for x in state.get("replied_to_ids", []))

    since_ids = state.get("hot_post_reply_since_ids", {})
    if not isinstance(since_ids, dict):
        since_ids = {}

    check_counts = state.get("hot_post_reply_check_counts", {})
    if not isinstance(check_counts, dict):
        check_counts = {}

    pagination_tokens = state.get("hot_post_reply_pagination_tokens", {})
    if not isinstance(pagination_tokens, dict):
        pagination_tokens = {}

    candidates: list[dict] = []
    state_changed = False

    watched_post_id_set = {str(post_id) for post_id in watched_post_ids}
    pruned_since_ids = {str(post_id): value for post_id, value in since_ids.items() if str(post_id) in watched_post_id_set}
    pruned_check_counts = {
        str(post_id): value
        for post_id, value in check_counts.items()
        if str(post_id) in watched_post_id_set
    }
    pruned_pagination_tokens = {
        str(post_id): value
        for post_id, value in pagination_tokens.items()
        if str(post_id) in watched_post_id_set
    }
    if (
        pruned_since_ids != since_ids
        or pruned_check_counts != check_counts
        or pruned_pagination_tokens != pagination_tokens
    ):
        log.info(
            "Pruned hot-post reply tracking maps. since_ids=%d->%d check_counts=%d->%d pagination_tokens=%d->%d",
            len(since_ids),
            len(pruned_since_ids),
            len(check_counts),
            len(pruned_check_counts),
            len(pagination_tokens),
            len(pruned_pagination_tokens),
        )
        state_changed = True
    since_ids = pruned_since_ids
    check_counts = pruned_check_counts
    pagination_tokens = pruned_pagination_tokens

    log.info(
        "Hot-post reply check loaded %d watched post(s) from %s: %s",
        len(watched_post_ids),
        EXTRA_QUOTE_WATCH_FILE,
        ", ".join(watched_post_ids),
    )

    for original_post_id in watched_post_ids:
        if len(candidates) >= MAX_HOT_POST_REPLIES_PER_CHECK:
            break

        original_post_id = str(original_post_id)
        previous_count = int(check_counts.get(original_post_id, 0) or 0)
        if HOT_POST_REPLY_FULL_RESCAN_EVERY_CHECKS > 0:
            current_count = (previous_count % HOT_POST_REPLY_FULL_RESCAN_EVERY_CHECKS) + 1
        else:
            current_count = previous_count + 1
        check_counts[original_post_id] = current_count
        state_changed = True

        full_rescan = False
        if HOT_POST_REPLY_FULL_RESCAN_EVERY_CHECKS > 0:
            full_rescan = current_count == HOT_POST_REPLY_FULL_RESCAN_EVERY_CHECKS
        if full_rescan and original_post_id in pagination_tokens:
            pagination_tokens.pop(original_post_id, None)
            state_changed = True

        # conversation_id finds replies in the original post's conversation.
        # We exclude this account and retweets; later filtering keeps only actual replies.
        query = f"conversation_id:{original_post_id} -from:{MY_USER_ID} -is:retweet"

        params = {
            "query": query,
            "max_results": HOT_POST_REPLY_SEARCH_API_MAX_RESULTS,
            "tweet.fields": "author_id,created_at,conversation_id,referenced_tweets,attachments,entities",
            "expansions": "author_id,attachments.media_keys",
            "media.fields": "media_key,type,url,preview_image_url",
        }

        since_id_used = ""
        if HOT_POST_REPLY_USE_SINCE_ID and not full_rescan:
            candidate_since_id = str(since_ids.get(original_post_id, "") or "")
            if candidate_since_id:
                params["since_id"] = candidate_since_id
                since_id_used = candidate_since_id
                log.info(
                    "Hot-post reply search for post_id=%s using since_id=%s",
                    original_post_id,
                    since_id_used,
                )

        resume_token = str(pagination_tokens.get(original_post_id, "") or "")
        if resume_token and not full_rescan:
            params["pagination_token"] = resume_token
            log.info("Resuming hot-post reply pagination for post_id=%s", original_post_id)

        def clear_invalid_hot_post_cursor() -> None:
            pagination_tokens.pop(original_post_id, None)
            state["hot_post_reply_pagination_tokens"] = dict(pagination_tokens)
            save_state(state, durable=True)

        try:
            result = x_paginated_get(
                x_quote_lookup_request,
                "/2/tweets/search/recent",
                params,
                max_pages=HOT_POST_REPLY_SEARCH_MAX_PAGES_PER_CHECK,
                label=f"hot-post replies for {original_post_id}",
                on_invalid_cursor=clear_invalid_hot_post_cursor,
            )
        except ApiError:
            log.exception("Failed to fetch hot-post replies for post %s", original_post_id)
            raise
        except Exception:
            log.exception("Unexpected failure fetching hot-post replies for post %s", original_post_id)
            raise

        replies = result.get("data", [])
        attach_media_to_tweets(replies, result.get("includes", {}))
        pagination = result.get("_pagination", {}) if isinstance(result.get("_pagination", {}), dict) else {}
        pagination_truncated = bool(pagination.get("truncated"))
        next_pagination_token = str(pagination.get("next_token") or "")
        log.info("Fetched %d hot-post conversation candidate(s) for post_id=%s", len(replies), original_post_id)
        log_json_debug("Hot-post reply candidates returned", replies)

        valid_replies = valid_tweets_sorted_by_id(replies, context="hot-post reply candidate")
        raw_ids = [int(str(reply["id"])) for reply in valid_replies]
        raw_highest_id = str(max(raw_ids)) if raw_ids else ""
        candidates_for_this_post = 0

        for reply in valid_replies:
            reply_id = str(reply.get("id", ""))
            author_id = str(reply.get("author_id", ""))

            if not reply_id or reply_id == str(original_post_id):
                continue

            if reply_id in replied_to_ids or reply_id in skipped_hot_reply_ids:
                log.info("Skipping hot-post reply %s: already replied/skipped", reply_id)
                continue

            if author_id == str(MY_USER_ID):
                log.info("Skipping hot-post reply %s: authored by own account", reply_id)
                mark_hot_post_reply_skipped(
                    state,
                    reply_id,
                    reason="own_account",
                    original_post_id=str(original_post_id),
                    retryable=False,
                )
                state_changed = True
                continue

            refs = reply.get("referenced_tweets", []) or []
            if not any(ref.get("type") == "replied_to" for ref in refs):
                log.info(
                    "Skipping hot-post candidate %s: not an ordinary reply. referenced_tweets=%s",
                    reply_id,
                    refs,
                )
                mark_hot_post_reply_skipped(
                    state,
                    reply_id,
                    reason="not_ordinary_reply",
                    original_post_id=str(original_post_id),
                    retryable=False,
                )
                state_changed = True
                continue

            if not reply_target_is_directly_eligible(reply):
                reason = "target_does_not_directly_mention_account"
                log.info(
                    "Skipping hot-post reply %s before candidate limiting: "
                    "target is not directly reply-eligible",
                    reply_id,
                )
                drafts = state.get("pending_ai_reply_drafts", {})
                pending_key = pending_ai_reply_draft_key(reply_id, "hot_post_reply")
                pending_record = drafts.get(pending_key) if isinstance(drafts, dict) else None
                if isinstance(pending_record, dict):
                    log_event(
                        "ai_reply_pipeline_outcome",
                        status="posting_failed_terminal",
                        lane="hot_post_reply",
                        target_id=reply_id,
                        reply_post_id="",
                        strategy_version=pending_record.get("strategy_version"),
                        mode=pending_record.get("mode"),
                        reviewer_verdict=pending_record.get("reviewer_verdict"),
                        failure_reason="reply_not_permitted_preflight",
                    )
                    clear_pending_ai_reply(state, reply_id, "hot_post_reply")
                record_terminal_reply_evaluation(
                    state,
                    target_id=reply_id,
                    lane="hot_post_reply",
                    reason=reason,
                    outcome="reply_not_permitted",
                )
                mark_hot_post_reply_skipped(
                    state,
                    reply_id,
                    reason=reason,
                    original_post_id=original_post_id,
                    retryable=False,
                )
                log_event(
                    "reply_target_terminal",
                    lane="hot_post_reply",
                    target_id=reply_id,
                    outcome="reply_not_permitted",
                    reason=reason,
                )
                state_changed = True
                continue

            reply["_source"] = "hot_post_reply"
            reply["_hot_original_post_id"] = str(original_post_id)

            cache_tweet(
                state,
                tweet_id=reply_id,
                text=reply.get("text", ""),
                author_id=author_id,
                conversation_id=str(reply.get("conversation_id", reply_id)),
                referenced_tweets=reply.get("referenced_tweets", []),
                created_at=reply.get("created_at"),
                post_type="hot_post_reply",
            )

            candidates.append(reply)
            candidates_for_this_post += 1
            state_changed = True

            if len(candidates) >= MAX_HOT_POST_REPLIES_PER_CHECK:
                break

        watermark_updated = False
        if HOT_POST_REPLY_USE_SINCE_ID and raw_highest_id and candidates_for_this_post == 0 and not pagination_truncated:
            old_since = str(since_ids.get(original_post_id, "") or "")
            if not old_since or int(raw_highest_id) > int(old_since):
                since_ids[original_post_id] = raw_highest_id
                watermark_updated = True
                state_changed = True
                log.info(
                    "Updated hot-post reply since_id for post_id=%s to %s after no usable candidates",
                    original_post_id,
                    raw_highest_id,
                )
        if pagination_truncated:
            log.warning(
                "Not updating hot-post reply since_id for post_id=%s because pagination was truncated",
                original_post_id,
            )
            if next_pagination_token:
                pagination_tokens[original_post_id] = next_pagination_token
                state_changed = True
        elif original_post_id in pagination_tokens:
            pagination_tokens.pop(original_post_id, None)
            state_changed = True

        log_event(
            "hot_search",
            lane="hot_post",
            original_post_id=original_post_id,
            raw_count=len(replies),
            usable_count=candidates_for_this_post,
            since_id_used=since_id_used or None,
            full_rescan=full_rescan,
            watermark_updated=watermark_updated,
            watermark=since_ids.get(original_post_id),
        )

    state["hot_post_reply_since_ids"] = since_ids
    state["hot_post_reply_check_counts"] = check_counts
    state["hot_post_reply_pagination_tokens"] = pagination_tokens

    if state_changed:
        save_state(state)

    log.info("Hot-post reply check returning %d candidate(s)", len(candidates))
    return candidates

def mark_hot_post_reply_skipped(
    state: dict,
    reply_id: str,
    *,
    reason: str = "unspecified",
    original_post_id: str | None = None,
    retryable: bool | None = None,
) -> None:
    """Mark hot post reply skipped."""
    reply_id = str(reply_id)
    if not reply_id:
        return

    state["skipped_hot_reply_ids"] = append_unique_capped(
        state.get("skipped_hot_reply_ids", []),
        reply_id,
        2000,
    )

    if retryable is None:
        retryable = False

    records = state.get("skipped_hot_reply_records", {})
    if not isinstance(records, dict):
        records = {}

    records[reply_id] = {
        "reason": reason,
        "retryable": bool(retryable),
        "skipped_epoch": now_epoch(),
    }
    if original_post_id:
        records[reply_id]["original_post_id"] = str(original_post_id)

    # Keep the record map bounded without disturbing the older list field that
    # existing digest scripts already understand.
    if len(records) > 2500:
        trimmed_items = sorted(
            records.items(),
            key=lambda item: int(item[1].get("skipped_epoch", 0) or 0),
        )[-2000:]
        records = dict(trimmed_items)

    state["skipped_hot_reply_records"] = records
    log_event(
        "candidate_skipped",
        lane="hot_post",
        id=reply_id,
        reason=reason,
        original_post_id=original_post_id,
        retryable=bool(retryable),
    )


def maybe_mark_hot_post_reply_skipped(state: dict, candidate: dict, reason: str = "unspecified") -> None:
    """
    Mark a candidate as handled for the hot-post lane when appropriate.

    A tweet can arrive from both /mentions and the hot-post recent-search lane.
    When we de-duplicate those, we keep the normal mention object so
    last_seen_mention_id still advances, but annotate it with
    _also_hot_post_reply=True. If that mention is then skipped, this helper
    still records the ID in skipped_hot_reply_ids so the hot-post lane does not
    reconsider it later and ask Grok a second time.
    """
    if candidate.get("_source") == "hot_post_reply" or candidate.get("_also_hot_post_reply"):
        mark_hot_post_reply_skipped(
            state,
            str(candidate.get("id", "")),
            reason=reason,
            original_post_id=str(candidate.get("_hot_original_post_id", "") or "") or None,
        )


def dedupe_reply_candidates(mentions: list[dict], hot_post_replies: list[dict]) -> list[dict]:
    """
    Merge normal mention candidates and hot-post reply candidates by tweet ID.

    Normal mentions win when the same tweet is present in both sources. That
    preserves last_seen_mention_id handling and prevents the same tweet being
    sent to Grok twice in one check. The retained mention is annotated as also
    belonging to the hot-post lane, so any skip decision is remembered for the
    hot-post search path too.
    """
    mention_by_id: dict[str, dict] = {}
    combined: list[dict] = []
    duplicate_mentions = 0
    duplicate_hot_post_replies = 0

    for mention in mentions:
        mention_id = str(mention.get("id", ""))
        if not mention_id:
            log.info("Dropping mention candidate with no id: %s", mention)
            continue

        if mention_id in mention_by_id:
            duplicate_mentions += 1
            log.info("Dropping duplicate mention candidate id=%s", mention_id)
            continue

        mention_by_id[mention_id] = mention
        combined.append(mention)

    seen_ids = set(mention_by_id)

    for hot_post_reply in hot_post_replies:
        reply_id = str(hot_post_reply.get("id", ""))
        if not reply_id:
            log.info("Dropping hot-post reply candidate with no id: %s", hot_post_reply)
            continue

        if reply_id in mention_by_id:
            duplicate_hot_post_replies += 1
            retained_mention = mention_by_id[reply_id]
            retained_mention["_also_hot_post_reply"] = True

            hot_original_post_id = hot_post_reply.get("_hot_original_post_id")
            if hot_original_post_id:
                retained_mention["_hot_original_post_id"] = str(hot_original_post_id)

            log.info(
                "Dropping duplicate hot-post reply candidate %s: already present as a normal mention; "
                "retained mention candidate marked as also_hot_post_reply",
                reply_id,
            )
            continue

        if reply_id in seen_ids:
            duplicate_hot_post_replies += 1
            log.info("Dropping duplicate hot-post reply candidate id=%s", reply_id)
            continue

        seen_ids.add(reply_id)
        combined.append(hot_post_reply)

    original_count = len(mentions) + len(hot_post_replies)
    if duplicate_mentions or duplicate_hot_post_replies or len(combined) != original_count:
        log.info(
            "Reply candidate de-duplication: mentions=%d hot_post_replies=%d combined=%d "
            "duplicate_mentions=%d duplicate_hot_post_replies=%d",
            len(mentions),
            len(hot_post_replies),
            len(combined),
            duplicate_mentions,
            duplicate_hot_post_replies,
        )

    return combined


